const DND_SPELLS=[{"id":"acid_splash","level":0,"name":"Acid Splash","nameEn":"Acid Splash","school":"Evocation","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You hurl a bubble of acid. Choose one creature within range, or two creatures within 5 feet of each other. A target must succeed on a Dexterity saving throw or take 1d6 acid damage. This spell's damage increases by 1d6 at levels 5 (2d6), 11 (3d6), and 17 (4d6)."},{"id":"blade_ward","level":0,"name":"Blade Ward","nameEn":"Blade Ward","school":"Abjuration","castingTime":"1 Action","range":"Self","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You trace a sigil of warding in the air. Until the end of your next turn, you have resistance against bludgeoning, piercing, and slashing damage dealt by weapon attacks."},{"id":"chill_touch","level":0,"name":"Chill Touch","nameEn":"Chill Touch","school":"Necromancy","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You create a ghostly, skeletal hand. Make a ranged spell attack against a creature. On a hit, it takes 1d8 necrotic damage and can't regain hit points until the start of your next turn. If the target is undead, it also has disadvantage on attack rolls against you until then. The damage increases at higher levels."},{"id":"dancing_lights","level":0,"name":"Dancing Lights","nameEn":"Dancing Lights","school":"Illusion","castingTime":"1 Action","range":"120 feet","components":"V, S, M (a bit of phosphorus or a glowworm)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You create up to four torch-sized lights, making them appear as torches, lanterns, or glowing orbs that hover for the duration, or you combine them into one Medium glowing humanoid form. As a bonus action you can move the lights up to 60 feet."},{"id":"druidcraft","level":0,"name":"Druidcraft","nameEn":"Druidcraft","school":"Transmutation","castingTime":"1 Action","range":"30 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You create a minor nature effect: predict the weather for the next 24 hours, make a flower blossom or a seed pod open, create a harmless sensory effect, or instantly light or snuff out a small flame."},{"id":"eldritch_blast","level":0,"name":"Eldritch Blast","nameEn":"Eldritch Blast","school":"Evocation","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You hurl a beam of crackling energy. Make a ranged spell attack against a creature; on a hit it takes 1d10 force damage. The spell creates more beams at higher levels (two at 5th, three at 11th, four at 17th), and you can aim them at the same or different targets."},{"id":"elementalism","level":0,"name":"Elementalism","nameEn":"Elementalism","school":"Transmutation","castingTime":"1 Action","range":"30 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You exert control over the elements, creating one of the following effects within range:\n\nBeckon Air. You create a breeze strong enough to ripple cloth, stir dust, rustle leaves, and close open doors and shutters, all in a 5-foot Cube. Doors and shutters being held open by someone or something aren't affected.\n\nBeckon Earth. You create a thin shroud of dust or sand that covers surfaces in a 5-foot-square area, or you cause a single word to appear in your handwriting in a patch of dirt or sand.\n\nBeckon Fire. You create a thin cloud of harmless embers and colored, scented smoke in a 5-foot Cube. You choose the color and scent, and the embers can light candles, torches, or lamps in that area. The smoke's scent lingers for 1 minute.\n\nBeckon Water. You create a spray of cool mist that lightly dampens creatures and objects in a 5-foot Cube. Alternatively, you create 1 cup of clean water either in an open container or on a surface, and the water evaporates in 1 minute.\n\nSculpt Element. You cause dirt, sand, fire, smoke, mist, or water that can fit in a 1-foot Cube to assume a crude shape (such as that of a creature or an object) for 1 hour."},{"id":"fire_bolt","level":0,"name":"Fire Bolt","nameEn":"Fire Bolt","school":"Evocation","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You hurl a mote of fire at a creature or object. Make a ranged spell attack; on a hit the target takes 1d10 fire damage. A flammable object hit by this spell ignites if it isn't being worn or carried. The damage increases at higher levels."},{"id":"friends","level":0,"name":"Friends","nameEn":"Friends","school":"Enchantment","castingTime":"1 Action","range":"Self","components":"S, M (a bit of makeup)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"For the duration, you have advantage on all Charisma checks directed at one creature that isn't hostile to you. When the spell ends, the creature realizes you used magic to influence its mood and becomes hostile toward you."},{"id":"guidance","level":0,"name":"Guidance","nameEn":"Guidance","school":"Divination","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You touch a willing creature. Once before the spell ends, it can roll a d4 and add the result to one ability check of its choice."},{"id":"light","level":0,"name":"Light","nameEn":"Light","school":"Evocation","castingTime":"1 Action","range":"Touch","components":"V, M (a firefly or phosphorescent moss)","duration":"1 hour","concentration":false,"ritual":false,"description":"You touch one object no larger than 10 feet in any dimension. Until the spell ends, the object sheds bright light in a 20-foot radius and dim light for an additional 20 feet. If you target an object held or worn by a hostile creature, it can make a Dexterity saving throw to avoid the spell."},{"id":"mage_hand","level":0,"name":"Mage Hand","nameEn":"Mage Hand","school":"Conjuration","castingTime":"1 Action","range":"30 feet","components":"V, S","duration":"1 minute","concentration":false,"ritual":false,"description":"A spectral floating hand appears at a point you choose within range. You can use an action to control the hand and manipulate objects, open doors and containers, or pour out a vial's contents. The hand can carry up to 10 pounds and can't attack, activate magic items, or carry more than 10 pounds."},{"id":"mending","level":0,"name":"Mending","nameEn":"Mending","school":"Transmutation","castingTime":"1 minute","range":"Touch","components":"V, S, M (two lodestones)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"This spell repairs a single break or tear in an object you touch, such as a torn cloak or a broken chain link, as long as the break is no larger than 1 foot in any dimension. It can't restore magic to a magic item."},{"id":"message","level":0,"name":"Message","nameEn":"Message","school":"Transmutation","castingTime":"1 Action","range":"120 feet","components":"S, M (a copper wire)","duration":"1 round","concentration":false,"ritual":false,"description":"You point toward a creature within range and whisper a message. Only that creature hears it and can reply in a whisper only you can hear. You can cast this spell through solid objects if you are familiar with the target and know it's beyond the barrier."},{"id":"mind_sliver","level":0,"name":"Mind Sliver","nameEn":"Mind Sliver","school":"Enchantment","castingTime":"1 Action","range":"60 feet","components":"V","duration":"1 round","concentration":false,"ritual":false,"description":"You drive a disorienting spike of psychic energy into the mind of one creature. It must succeed on an Intelligence saving throw or take 1d6 psychic damage and subtract 1d4 from the next saving throw it makes before the end of your next turn. The damage increases at higher levels."},{"id":"minor_illusion","level":0,"name":"Minor Illusion","nameEn":"Minor Illusion","school":"Illusion","castingTime":"1 Action","range":"30 feet","components":"S, M (a bit of fleece)","duration":"1 minute","concentration":false,"ritual":false,"description":"You create a sound or an image of an object within range that lasts for the duration. The illusion can't create sound and image at the same time. Physical interaction or an Investigation check against your spell save DC reveals it to be an illusion."},{"id":"poison_spray","level":0,"name":"Poison Spray","nameEn":"Poison Spray","school":"Necromancy","castingTime":"1 Action","range":"10 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You extend your hand toward a creature within range and project a puff of noxious gas. The target must succeed on a Constitution saving throw or take 1d12 poison damage. The damage increases at higher levels."},{"id":"prestidigitation","level":0,"name":"Prestidigitation","nameEn":"Prestidigitation","school":"Transmutation","castingTime":"1 Action","range":"10 feet","components":"V, S","duration":"Up to 1 hour","concentration":false,"ritual":false,"description":"This spell performs minor magical tricks: create a harmless sensory effect, light or snuff out a small flame, clean or soil an object, chill/warm/flavor up to 1 cubic foot of material, make a small mark or symbol, or create a nonmagical trinket or illusory image that lasts until the end of your next turn."},{"id":"produce_flame","level":0,"name":"Produce Flame","nameEn":"Produce Flame","school":"Conjuration","castingTime":"1 Bonus Action","range":"Self","components":"V, S","duration":"10 minutes","concentration":false,"ritual":false,"description":"A flickering flame appears in your hand, shedding bright light in a 10-foot radius. You can hurl the flame at a creature within 30 feet as part of casting this spell or as an action on a later turn: make a ranged spell attack, dealing 1d8 fire damage on a hit. The damage increases at higher levels."},{"id":"ray_of_frost","level":0,"name":"Ray of Frost","nameEn":"Ray of Frost","school":"Evocation","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A frigid beam of blue-white light streaks toward a creature. Make a ranged spell attack; on a hit it takes 1d8 cold damage, and its speed is reduced by 10 feet until the start of your next turn. The damage increases at higher levels."},{"id":"resistance","level":0,"name":"Resistance","nameEn":"Resistance","school":"Abjuration","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You touch a willing creature. Once before the spell ends, it can roll a d4 and add the result to one saving throw of its choice."},{"id":"sacred_flame","level":0,"name":"Sacred Flame","nameEn":"Sacred Flame","school":"Evocation","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"Flame-like radiance descends on a creature within range. It must succeed on a Dexterity saving throw or take 1d8 radiant damage. The target gains no benefit from cover for this saving throw. The damage increases at higher levels."},{"id":"shillelagh","level":0,"name":"Shillelagh","nameEn":"Shillelagh","school":"Transmutation","castingTime":"1 Bonus Action","range":"Touch","components":"V, S, M (mistletoe)","duration":"1 minute","concentration":false,"ritual":false,"description":"The wood of a club or quarterstaff you hold is imbued with nature's power. For the duration, you can use your spellcasting ability for attack and damage rolls with it, its damage die becomes a d8, and it counts as magical."},{"id":"shocking_grasp","level":0,"name":"Shocking Grasp","nameEn":"Shocking Grasp","school":"Evocation","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"Lightning springs from your hand. Make a melee spell attack against a creature, with advantage if it is wearing armor made of metal. On a hit it takes 1d8 lightning damage and can't take reactions until the start of its next turn. The damage increases at higher levels."},{"id":"sorcerous_burst","level":0,"name":"Sorcerous Burst","nameEn":"Sorcerous Burst","school":"Evocation","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You cast sorcerous energy at one creature or object within range. Make a ranged attack roll against the target. On a hit, the target takes 1d8 damage of a type you choose: Acid, Cold, Fire, Lightning, Poison, Psychic, or Thunder.\n\nIf you roll an 8 on a d8 for this spell, you can roll another d8, and add it to the damage. When you cast this spell, the maximum number of these d8s you can add to the spell's damage equals your spellcasting ability modifier.\n\nCantrip Upgrade. This damage increases by 1d8 when you reach level 5 (2d8), 11 (3d8), and 17 (4d8)."},{"id":"spare_the_dying","level":0,"name":"Spare the Dying","nameEn":"Spare the Dying","school":"Necromancy","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You touch a living creature that has 0 hit points. The creature becomes stable. This spell has no effect on undead or constructs."},{"id":"starry_wisp","level":0,"name":"Starry Wisp","nameEn":"Starry Wisp","school":"Evocation","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You launch a mote of light at one creature or object within range. Make a ranged spell attack against the target. On a hit, the target takes 1d8 Radiant damage, and until the end of your next turn, it emits Dim Light in a 10-foot radius and can't benefit from the Invisible condition.\n\nCantrip Upgrade. The damage increases by 1d8 when you reach levels 5 (2d8), 11 (3d8), and 17 (4d8)."},{"id":"thaumaturgy","level":0,"name":"Thaumaturgy","nameEn":"Thaumaturgy","school":"Transmutation","castingTime":"1 Action","range":"30 feet","components":"V","duration":"Up to 1 minute","concentration":false,"ritual":false,"description":"You manifest a minor wonder within range: a booming voice, flickering flames, harmless tremors, an eerie sound, a door or window flying open or slamming shut, or altering the appearance of your eyes. You can have up to three such effects active at once."},{"id":"thorn_whip","level":0,"name":"Thorn Whip","nameEn":"Thorn Whip","school":"Transmutation","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a thorn)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You create a vine-like whip covered in thorns that lashes out at a creature. Make a melee spell attack; on a hit it takes 1d6 piercing damage, and if it is Large or smaller you pull it up to 10 feet closer to you. The damage increases at higher levels."},{"id":"thunderclap","level":0,"name":"Thunderclap","nameEn":"Thunderclap","school":"Evocation","castingTime":"1 Action","range":"Self (5-foot radius)","components":"S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You create a burst of thunderous sound that can be heard up to 100 feet away. Each creature within 5 feet of you, other than you, must succeed on a Constitution saving throw or take 1d6 thunder damage. The damage increases at higher levels."},{"id":"toll_the_dead","level":0,"name":"Toll the Dead","nameEn":"Toll the Dead","school":"Necromancy","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You point at a creature within range, and a mournful bell tolls. It must succeed on a Wisdom saving throw or take 1d8 necrotic damage (1d12 if it is missing any of its hit points). The damage increases at higher levels."},{"id":"true_strike","level":0,"name":"True Strike","nameEn":"True Strike","school":"Divination","castingTime":"1 Action","range":"30 feet","components":"S, M (a weapon with which you have proficiency and that is worth 1+ CP)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You point at a target within range. Your magic grants you a brief insight into its defenses. On your next turn, you gain advantage on your first attack roll against the target, provided this spell hasn't ended."},{"id":"vicious_mockery","level":0,"name":"Vicious Mockery","nameEn":"Vicious Mockery","school":"Enchantment","castingTime":"1 Action","range":"60 feet","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You unleash a string of insults laced with subtle enchantments at a creature you can see. It must succeed on a Wisdom saving throw or take 1d4 psychic damage and have disadvantage on the next attack roll it makes before the end of its next turn. The damage increases at higher levels."},{"id":"word_of_radiance","level":0,"name":"Word of Radiance","nameEn":"Word of Radiance","school":"Evocation","castingTime":"1 Action","range":"5 feet","components":"V, M (a holy symbol)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You utter a divine word, and burning radiance erupts from you. Each creature of your choice that you can see within 5 feet must succeed on a Constitution saving throw or take 1d6 radiant damage. The damage increases at higher levels."},{"id":"alarm","level":1,"name":"Alarm","nameEn":"Alarm","school":"Abjuration","castingTime":"1 minute","range":"30 feet","components":"V, S, M (a tiny bell and silver wire)","duration":"8 hours","concentration":false,"ritual":true,"description":"You set an alarm against intrusion. Choose a door, window, or area within range no larger than a 20-foot cube. Until the spell ends, an alarm alerts you whenever a Tiny or larger creature touches or enters the warded area. You can designate creatures that won't set it off, and choose a mental or audible alarm."},{"id":"animal_friendship","level":1,"name":"Animal Friendship","nameEn":"Animal Friendship","school":"Enchantment","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a morsel of food)","duration":"24 hours","concentration":false,"ritual":false,"description":"You convince a beast that you mean it no harm. Choose a beast within range with an Intelligence of 3 or lower. It must make a Wisdom saving throw or be charmed by you for the duration. At higher levels you can affect additional beasts."},{"id":"armor_of_agathys","level":1,"name":"Armor of Agathys","nameEn":"Armor of Agathys","school":"Abjuration","castingTime":"1 Bonus Action","range":"Self","components":"V, S, M (a cup of water)","duration":"1 hour","concentration":false,"ritual":false,"description":"Protective magical frost surrounds you. You gain 5 temporary hit points. If a creature hits you with a melee attack while you have these hit points, it takes 5 cold damage. Both values increase by 5 for each slot level above 1st."},{"id":"arms_of_hadar","level":1,"name":"Arms of Hadar","nameEn":"Arms of Hadar","school":"Conjuration","castingTime":"1 Action","range":"Self (10-foot radius)","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You invoke the power of Hadar. Tendrils of dark energy erupt from you. Each creature within 10 feet must make a Strength saving throw, taking 2d6 necrotic damage on a failure (half on a success) and unable to take reactions until its next turn on a failure. The damage increases at higher levels."},{"id":"bane","level":1,"name":"Bane","nameEn":"Bane","school":"Enchantment","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a drop of blood)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Up to three creatures of your choice must succeed on a Charisma saving throw or, for the duration, subtract a d4 from each attack roll and saving throw they make. At higher levels you can target additional creatures."},{"id":"bless","level":1,"name":"Bless","nameEn":"Bless","school":"Enchantment","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a sprinkling of holy water)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You bless up to three creatures of your choice within range. Whenever a target makes an attack roll or a saving throw before the spell ends, it can add a d4 to the roll. At higher levels you can target additional creatures."},{"id":"burning_hands","level":1,"name":"Burning Hands","nameEn":"Burning Hands","school":"Evocation","castingTime":"1 Action","range":"Self (15-foot cone)","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A thin sheet of flames shoots from your fingertips. Each creature in a 15-foot cone must make a Dexterity saving throw, taking 3d6 fire damage on a failure or half as much on a success. Flammable objects in the area that aren't worn or carried ignite. The damage increases by 1d6 per slot level above 1st."},{"id":"charm_person","level":1,"name":"Charm Person","nameEn":"Charm Person","school":"Enchantment","castingTime":"1 Action","range":"30 feet","components":"V, S","duration":"1 hour","concentration":false,"ritual":false,"description":"You attempt to charm a humanoid within range. It must succeed on a Wisdom saving throw (with advantage if you or your companions are fighting it) or be charmed by you until the spell ends or you or your companions harm it. At higher levels you can target additional humanoids."},{"id":"chromatic_orb","level":1,"name":"Chromatic Orb","nameEn":"Chromatic Orb","school":"Evocation","castingTime":"1 Action","range":"90 feet","components":"V, S, M (a 50 gp diamond)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You hurl a 4-inch sphere of energy at a creature. Choose acid, cold, fire, lightning, poison, or thunder, then make a ranged spell attack; on a hit the target takes 3d8 damage of the chosen type. The damage increases by 1d8 per slot level above 1st."},{"id":"color_spray","level":1,"name":"Color Spray","nameEn":"Color Spray","school":"Illusion","castingTime":"1 Action","range":"Self (15-foot cone)","components":"V, S, M (powder or sand of red, yellow, and blue)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A dazzling array of flashing colored light springs from your hand. Roll 6d10; that is the total hit points of creatures this spell can blind. Starting with the lowest current hit points, creatures in a 15-foot cone are blinded until the end of your next turn. The hit point total increases at higher levels."},{"id":"command","level":1,"name":"Command","nameEn":"Command","school":"Enchantment","castingTime":"1 Action","range":"60 feet","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You speak a one-word command to a creature you can see within range. It must succeed on a Wisdom saving throw or follow the command on its next turn (such as Approach, Drop, Flee, Grovel, or Halt). At higher levels you can affect additional creatures."},{"id":"compelled_duel","level":1,"name":"Compelled Duel","nameEn":"Compelled Duel","school":"Enchantment","castingTime":"1 Bonus Action","range":"30 feet","components":"V","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You try to compel a creature into a duel. One creature within range must make a Wisdom saving throw; on a failure it has disadvantage on attack rolls against creatures other than you and can't willingly move more than 30 feet away from you while the spell lasts."},{"id":"comprehend_languages","level":1,"name":"Comprehend Languages","nameEn":"Comprehend Languages","school":"Divination","castingTime":"1 Action","range":"Self","components":"V, S, M (a pinch of soot and salt)","duration":"1 hour","concentration":false,"ritual":true,"description":"For the duration, you understand the literal meaning of any spoken language you hear, and you can read any written language you see (touching the surface on which words are written). It doesn't decode secret messages or symbols."},{"id":"create_or_destroy_water","level":1,"name":"Create or Destroy Water","nameEn":"Create or Destroy Water","school":"Transmutation","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a drop of water or a pinch of dust)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You either create up to 10 gallons of clean water in an open container or as rain in a 30-foot cube, or you destroy an equal amount of water (or fog) in a 30-foot cube. The amount increases at higher levels."},{"id":"cure_wounds","level":1,"name":"Cure Wounds","nameEn":"Cure Wounds","school":"Abjuration","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A creature you touch regains hit points equal to 1d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs. The healing increases by 1d8 per slot level above 1st."},{"id":"detect_evil_and_good","level":1,"name":"Detect Evil and Good","nameEn":"Detect Evil and Good","school":"Divination","castingTime":"1 Action","range":"Self","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"For the duration, you know the location of any aberration, celestial, elemental, fey, fiend, or undead within 30 feet, as well as where any place or object has been consecrated or desecrated."},{"id":"detect_magic","level":1,"name":"Detect Magic","nameEn":"Detect Magic","school":"Divination","castingTime":"1 Action","range":"Self","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":true,"description":"For the duration, you sense the presence of magic within 30 feet. If you sense magic this way, you can use an action to see a faint aura around any visible creature or object that bears magic, and learn its school of magic, if any."},{"id":"detect_poison_and_disease","level":1,"name":"Detect Poison and Disease","nameEn":"Detect Poison and Disease","school":"Divination","castingTime":"1 Action","range":"Self","components":"V, S, M (a yew leaf)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":true,"description":"For the duration, you sense the presence and location of poisons, poisonous creatures, and diseases within 30 feet. You also identify the kind of poison, creature, or disease in each case."},{"id":"disguise_self","level":1,"name":"Disguise Self","nameEn":"Disguise Self","school":"Illusion","castingTime":"1 Action","range":"Self","components":"V, S","duration":"1 hour","concentration":false,"ritual":false,"description":"You make yourself - including clothing, armor, weapons, and equipment - look different until the spell ends. You can change your apparent height, weight, and features. The changes are illusory; a creature can use its action to inspect you and make an Investigation check against your spell save DC to discern the disguise."},{"id":"dissonant_whispers","level":1,"name":"Dissonant Whispers","nameEn":"Dissonant Whispers","school":"Enchantment","castingTime":"1 Action","range":"60 feet","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You whisper a discordant melody only one creature can hear, wracking it with pain. It must make a Wisdom saving throw, taking 3d6 psychic damage on a failure (half on a success). On a failure it must immediately use its reaction to move away from you as far as its speed allows. The damage increases at higher levels."},{"id":"divine_favor","level":1,"name":"Divine Favor","nameEn":"Divine Favor","school":"Transmutation","castingTime":"1 Bonus Action","range":"Self","components":"V, S","duration":"1 minute","concentration":false,"ritual":false,"description":"Your prayer empowers you with divine radiance. Until the spell ends, your weapon attacks deal an extra 1d4 radiant damage on a hit."},{"id":"divine_smite","level":1,"name":"Divine Smite","nameEn":"Divine Smite","school":"Evocation","castingTime":"1 Bonus Action, which you take immediately after hitting a target with a Melee weapon or an Unarmed Strike","range":"Self","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"The target takes an extra 2d8 Radiant damage from the attack. The damage increases by 1d8 if the target is a Fiend or an Undead.\n\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 1."},{"id":"ensnaring_strike","level":1,"name":"Ensnaring Strike","nameEn":"Ensnaring Strike","school":"Conjuration","castingTime":"1 Bonus Action","range":"Self","components":"V","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"The next time you hit a creature with a weapon attack before the spell ends, a writhing mass of thorny vines appears. The target must succeed on a Strength saving throw or be restrained, taking 1d6 piercing damage at the start of each of its turns until it escapes. The damage increases at higher levels."},{"id":"entangle","level":1,"name":"Entangle","nameEn":"Entangle","school":"Conjuration","castingTime":"1 Action","range":"90 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Grasping weeds and vines sprout from the ground in a 20-foot square within range. Each creature there when you cast it must succeed on a Strength saving throw or be restrained. A restrained creature can use its action to make a Strength check to free itself. The area is difficult terrain while the spell lasts."},{"id":"expeditious_retreat","level":1,"name":"Expeditious Retreat","nameEn":"Expeditious Retreat","school":"Transmutation","castingTime":"1 Bonus Action","range":"Self","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"This spell lets you move at an incredible pace. When you cast it, and as a bonus action on each of your turns until it ends, you can take the Dash action."},{"id":"faerie_fire","level":1,"name":"Faerie Fire","nameEn":"Faerie Fire","school":"Evocation","castingTime":"1 Action","range":"60 feet","components":"V","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Each object in a 20-foot cube within range is outlined in light, and so is each creature there that fails a Dexterity saving throw. Affected creatures and objects shed dim light, can't benefit from being invisible, and attack rolls against them have advantage."},{"id":"false_life","level":1,"name":"False Life","nameEn":"False Life","school":"Necromancy","castingTime":"1 Action","range":"Self","components":"V, S, M (a small amount of alcohol or distilled spirits)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"Bolstering yourself with a necromantic facsimile of life, you gain 1d4 + 4 temporary hit points for the duration. The temporary hit points increase by 5 per slot level above 1st."},{"id":"feather_fall","level":1,"name":"Feather Fall","nameEn":"Feather Fall","school":"Transmutation","castingTime":"1 Reaction","range":"60 feet","components":"V, M (a small feather or piece of down)","duration":"1 minute","concentration":false,"ritual":false,"description":"Choose up to five falling creatures within range. A falling creature's rate of descent slows to 60 feet per round until the spell ends. If the creature lands before then, it takes no falling damage and can land on its feet."},{"id":"find_familiar","level":1,"name":"Find Familiar","nameEn":"Find Familiar","school":"Conjuration","castingTime":"1 hour","range":"10 feet","components":"V, S, M (10 gp of charcoal, incense, and herbs, consumed)","duration":"Instantaneous","concentration":false,"ritual":true,"description":"You gain the service of a familiar, a spirit that takes an animal form you choose. It is a celestial, fey, or fiend and obeys your commands. While it is within 100 feet, you can communicate telepathically and, as an action, see through its eyes. You can cast touch spells through it."},{"id":"fog_cloud","level":1,"name":"Fog Cloud","nameEn":"Fog Cloud","school":"Conjuration","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You create a 20-foot-radius sphere of fog centered on a point within range. The fog spreads around corners and heavily obscures the area. A wind of moderate or greater speed disperses it. The radius increases by 20 feet per slot level above 1st."},{"id":"goodberry","level":1,"name":"Goodberry","nameEn":"Goodberry","school":"Conjuration","castingTime":"1 Action","range":"Touch","components":"V, S, M (a sprig of mistletoe)","duration":"24 hours","concentration":false,"ritual":false,"description":"Up to ten berries appear in your hand, infused with magic for 24 hours. A creature can use its action to eat one berry, regaining 1 hit point, and a single berry provides enough nourishment to sustain a creature for one day."},{"id":"grease","level":1,"name":"Grease","nameEn":"Grease","school":"Conjuration","castingTime":"1 Action","range":"60 feet","components":"V, S, M (a bit of pork rind or butter)","duration":"1 minute","concentration":false,"ritual":false,"description":"Slick grease covers the ground in a 10-foot square centered on a point within range, turning it into difficult terrain. A creature standing there when you cast the spell must succeed on a Dexterity saving throw or fall prone, as must any creature that enters the area or ends its turn there."},{"id":"guiding_bolt","level":1,"name":"Guiding Bolt","nameEn":"Guiding Bolt","school":"Evocation","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"1 round","concentration":false,"ritual":false,"description":"A flash of light streaks toward a creature. Make a ranged spell attack; on a hit it takes 4d6 radiant damage, and the next attack roll made against it before the end of your next turn has advantage. The damage increases by 1d6 per slot level above 1st."},{"id":"hail_of_thorns","level":1,"name":"Hail of Thorns","nameEn":"Hail of Thorns","school":"Conjuration","castingTime":"1 Bonus Action","range":"Self","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"The next time you hit a creature with a ranged weapon attack before the spell ends, thorns rain down. The target and each creature within 5 feet of it must make a Dexterity saving throw, taking 1d10 piercing damage on a failure (half on a success). The damage increases at higher levels."},{"id":"healing_word","level":1,"name":"Healing Word","nameEn":"Healing Word","school":"Abjuration","castingTime":"1 Bonus Action","range":"60 feet","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A creature of your choice that you can see within range regains hit points equal to 1d4 + your spellcasting ability modifier. This spell has no effect on undead or constructs. The healing increases by 1d4 per slot level above 1st."},{"id":"hellish_rebuke","level":1,"name":"Hellish Rebuke","nameEn":"Hellish Rebuke","school":"Evocation","castingTime":"1 Reaction","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"Cast in response to being damaged by a creature within 60 feet, you point at the attacker and it is momentarily surrounded in flames. It must make a Dexterity saving throw, taking 2d10 fire damage on a failure or half as much on a success. The damage increases by 1d10 per slot level above 1st."},{"id":"heroism","level":1,"name":"Heroism","nameEn":"Heroism","school":"Enchantment","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"A willing creature you touch is imbued with bravery. Until the spell ends, it is immune to being frightened and gains temporary hit points equal to your spellcasting ability modifier at the start of each of its turns. At higher levels you can affect additional creatures."},{"id":"hex","level":1,"name":"Hex","nameEn":"Hex","school":"Enchantment","castingTime":"1 Bonus Action","range":"90 feet","components":"V, S, M (the petrified eye of a newt)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You place a curse on a creature within range. You deal an extra 1d6 necrotic damage to it whenever you hit it with an attack, and you choose one ability; the target has disadvantage on ability checks made with that ability. The duration lengthens at higher levels."},{"id":"hunters_mark","level":1,"name":"Hunter's Mark","nameEn":"Hunter's Mark","school":"Divination","castingTime":"1 Bonus Action","range":"90 feet","components":"V","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You mark a creature as your quarry. Until the spell ends, you deal an extra 1d6 damage whenever you hit it with a weapon attack, and you have advantage on Perception and Survival checks to find it. The duration lengthens at higher levels."},{"id":"ice_knife","level":1,"name":"Ice Knife","nameEn":"Ice Knife","school":"Conjuration","castingTime":"1 Action","range":"60 feet","components":"S, M (a drop of water or piece of ice)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You create a shard of ice and fling it at a creature. Make a ranged spell attack; on a hit it takes 1d10 piercing damage. Hit or miss, the shard then explodes, and each creature within 5 feet of the target must make a Dexterity saving throw or take 2d6 cold damage. The cold damage increases at higher levels."},{"id":"identify","level":1,"name":"Identify","nameEn":"Identify","school":"Divination","castingTime":"1 minute","range":"Touch","components":"V, S, M (a pearl worth 100 gp and an owl feather)","duration":"Instantaneous","concentration":false,"ritual":true,"description":"You touch a magic item or object. You learn its magical properties, how to use them, whether it requires attunement, and how many charges it has. You also learn whether any spells affect the item and what they are."},{"id":"illusory_script","level":1,"name":"Illusory Script","nameEn":"Illusory Script","school":"Illusion","castingTime":"1 minute","range":"Touch","components":"S, M (lead-based ink worth at least 10 gp, consumed)","duration":"10 days","concentration":false,"ritual":true,"description":"You write on parchment, paper, or another material and imbue it with an illusion. To everyone but you and creatures you designate, the writing appears as indecipherable script or different text of your choosing. A creature with truesight can read the hidden message."},{"id":"inflict_wounds","level":1,"name":"Inflict Wounds","nameEn":"Inflict Wounds","school":"Necromancy","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"Make a melee spell attack against a creature you can reach. On a hit, it takes 3d10 necrotic damage. The damage increases by 1d10 per slot level above 1st."},{"id":"jump","level":1,"name":"Jump","nameEn":"Jump","school":"Transmutation","castingTime":"1 Bonus Action","range":"Touch","components":"V, S, M (a grasshopper's hind leg)","duration":"1 minute","concentration":false,"ritual":false,"description":"You touch a creature. Until the spell ends, its jump distance is tripled."},{"id":"longstrider","level":1,"name":"Longstrider","nameEn":"Longstrider","school":"Transmutation","castingTime":"1 Action","range":"Touch","components":"V, S, M (a pinch of dirt)","duration":"1 hour","concentration":false,"ritual":false,"description":"You touch a creature. Until the spell ends, its speed increases by 10 feet. You can affect additional creatures at higher levels."},{"id":"mage_armor","level":1,"name":"Mage Armor","nameEn":"Mage Armor","school":"Abjuration","castingTime":"1 Action","range":"Touch","components":"V, S, M (a piece of cured leather)","duration":"8 hours","concentration":false,"ritual":false,"description":"You touch a willing creature that isn't wearing armor, and a protective magical force surrounds it. Its base AC becomes 13 + its Dexterity modifier. The spell ends if the target dons armor or you dismiss it as an action."},{"id":"magic_missile","level":1,"name":"Magic Missile","nameEn":"Magic Missile","school":"Evocation","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You create three glowing darts of magical force. Each dart hits a creature of your choice that you can see within range, dealing 1d4 + 1 force damage. The darts strike simultaneously and you can direct them at one creature or several. You create one additional dart per slot level above 1st."},{"id":"protection_from_evil_and_good","level":1,"name":"Protection from Evil and Good","nameEn":"Protection from Evil and Good","school":"Abjuration","castingTime":"1 Action","range":"Touch","components":"V, S, M (holy water or powdered silver and iron, consumed)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"Until the spell ends, one willing creature you touch is protected against aberrations, celestials, elementals, fey, fiends, and undead. Such creatures have disadvantage on attack rolls against the target, and can't charm, frighten, or possess it."},{"id":"purify_food_and_drink","level":1,"name":"Purify Food and Drink","nameEn":"Purify Food and Drink","school":"Transmutation","castingTime":"1 Action","range":"10 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":true,"description":"All nonmagical food and drink within a 5-foot-radius sphere centered on a point within range is purified and rendered free of poison and disease."},{"id":"ray_of_sickness","level":1,"name":"Ray of Sickness","nameEn":"Ray of Sickness","school":"Necromancy","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A ray of sickening greenish energy lashes out at a creature. Make a ranged spell attack; on a hit it takes 2d8 poison damage and must succeed on a Constitution saving throw or be poisoned until the end of your next turn. The damage increases by 1d8 per slot level above 1st."},{"id":"sanctuary","level":1,"name":"Sanctuary","nameEn":"Sanctuary","school":"Abjuration","castingTime":"1 Bonus Action","range":"30 feet","components":"V, S, M (a small silver mirror)","duration":"1 minute","concentration":false,"ritual":false,"description":"You ward a creature within range. Until the spell ends, any creature that targets the warded creature with an attack or harmful spell must first make a Wisdom saving throw; on a failure it must choose a new target or lose the attack or spell. The ward ends if the warded creature attacks or casts a spell on an enemy."},{"id":"searing_smite","level":1,"name":"Searing Smite","nameEn":"Searing Smite","school":"Evocation","castingTime":"1 Bonus Action","range":"Self","components":"V","duration":"1 minute","concentration":false,"ritual":false,"description":"The next time you hit a creature with a melee weapon attack before the spell ends, it flares with white-hot intensity, taking an extra 1d6 fire damage and igniting. Until the spell ends, it takes 1d6 fire damage at the start of each of its turns unless it makes a Constitution save to end the effect. The damage increases at higher levels."},{"id":"shield","level":1,"name":"Shield","nameEn":"Shield","school":"Abjuration","castingTime":"1 Reaction","range":"Self","components":"V, S","duration":"1 round","concentration":false,"ritual":false,"description":"An invisible barrier of magical force appears and protects you. Until the start of your next turn, you have a +5 bonus to AC, including against the triggering attack, and you take no damage from magic missile."},{"id":"shield_of_faith","level":1,"name":"Shield of Faith","nameEn":"Shield of Faith","school":"Abjuration","castingTime":"1 Bonus Action","range":"60 feet","components":"V, S, M (a small parchment with holy text)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"A shimmering field appears around a creature of your choice within range, granting it a +2 bonus to AC for the duration."},{"id":"silent_image","level":1,"name":"Silent Image","nameEn":"Silent Image","school":"Illusion","castingTime":"1 Action","range":"60 feet","components":"V, S, M (a bit of fleece)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You create the image of an object, creature, or other visible phenomenon no larger than a 15-foot cube. The image is purely visual and includes no sound, smell, or other effects. You can move it as an action. Physical interaction or an Investigation check against your save DC reveals it as an illusion."},{"id":"sleep","level":1,"name":"Sleep","nameEn":"Sleep","school":"Enchantment","castingTime":"1 Action","range":"90 feet","components":"V, S, M (a pinch of fine sand, rose petals, or a cricket)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Roll 5d8; the total is how many hit points of creatures this spell can affect. Starting with the lowest current hit points, creatures within 20 feet of a point you choose fall unconscious until the spell ends, take damage, or someone uses an action to wake them. The total increases by 2d8 per slot level above 1st."},{"id":"speak_with_animals","level":1,"name":"Speak with Animals","nameEn":"Speak with Animals","school":"Divination","castingTime":"1 Action","range":"Self","components":"V, S","duration":"10 minutes","concentration":false,"ritual":true,"description":"For the duration, you can comprehend and verbally communicate with beasts. You can question them about recent events and locations within the limits of their intelligence and perception."},{"id":"tashas_hideous_laughter","level":1,"name":"Tasha's Hideous Laughter","nameEn":"Tasha's Hideous Laughter","school":"Enchantment","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a tiny tart and a feather)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"A creature of your choice perceives everything as hilariously funny. It must succeed on a Wisdom saving throw or fall prone, becoming incapacitated and unable to stand. It can repeat the save at the end of each of its turns, or when it takes damage."},{"id":"tensers_floating_disk","level":1,"name":"Tenser's Floating Disk","nameEn":"Tenser's Floating Disk","school":"Conjuration","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a drop of mercury)","duration":"1 hour","concentration":false,"ritual":true,"description":"This spell creates a floating, horizontal disk of force about 3 feet in diameter that can hold up to 500 pounds. It hovers 3 feet off the ground and moves to remain within 20 feet of you, following you over most terrain."},{"id":"thunderous_smite","level":1,"name":"Thunderous Smite","nameEn":"Thunderous Smite","school":"Evocation","castingTime":"1 Bonus Action","range":"Self","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"The next time you hit with a melee weapon attack before the spell ends, your weapon rings with thunder, dealing an extra 2d6 thunder damage. The target must succeed on a Strength saving throw or be pushed 10 feet away and knocked prone."},{"id":"thunderwave","level":1,"name":"Thunderwave","nameEn":"Thunderwave","school":"Evocation","castingTime":"1 Action","range":"Self (15-foot cube)","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A wave of thunderous force sweeps out from you. Each creature in a 15-foot cube must make a Constitution saving throw, taking 2d8 thunder damage on a failure and being pushed 10 feet away from you, or half damage and no push on a success. The damage increases by 1d8 per slot level above 1st."},{"id":"unseen_servant","level":1,"name":"Unseen Servant","nameEn":"Unseen Servant","school":"Conjuration","castingTime":"1 Action","range":"60 feet","components":"V, S, M (a piece of string and a bit of wood)","duration":"1 hour","concentration":false,"ritual":true,"description":"You create an invisible, mindless, shapeless force that performs simple tasks at your command until the spell ends. It can fetch things, clean, mend, fold clothes, light fires, serve food, and pour wine, but can't attack and has AC 10, 1 hit point, and a Strength of 2."},{"id":"witch_bolt","level":1,"name":"Witch Bolt","nameEn":"Witch Bolt","school":"Evocation","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a twig from a lightning-struck tree)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"A beam of crackling energy lances out at a creature. Make a ranged spell attack; on a hit it takes 1d12 lightning damage, and on each later turn you can use your action to deal 1d12 lightning damage automatically. The initial damage increases at higher levels."},{"id":"wrathful_smite","level":1,"name":"Wrathful Smite","nameEn":"Wrathful Smite","school":"Necromancy","castingTime":"1 Bonus Action","range":"Self","components":"V","duration":"1 minute","concentration":false,"ritual":false,"description":"The next time you hit with a melee weapon attack before the spell ends, your attack deals an extra 1d6 psychic damage. The target must succeed on a Wisdom saving throw or be frightened of you until the spell ends; it can use its action to make a Wisdom check to end the effect."},{"id":"aid","level":2,"name":"Aid","nameEn":"Aid","school":"Abjuration","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a tiny strip of white cloth)","duration":"8 hours","concentration":false,"ritual":false,"description":"Your spell bolsters up to three creatures within range. Each target's hit point maximum and current hit points increase by 5 for the duration. The bonus increases by 5 per slot level above 2nd."},{"id":"alter_self","level":2,"name":"Alter Self","nameEn":"Alter Self","school":"Transmutation","castingTime":"1 Action","range":"Self","components":"V, S","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You assume a different form. Choose one option each time you could change: adapt to breathe water and swim, change your appearance, or grow natural weapons that count as magical and deal 1d6 damage. You can change the option as an action."},{"id":"animal_messenger","level":2,"name":"Animal Messenger","nameEn":"Animal Messenger","school":"Enchantment","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a morsel of food)","duration":"24 hours","concentration":false,"ritual":true,"description":"Using a Tiny beast within range, you send a message. Name a recipient and location, and the beast travels there to deliver a short message you specify. The duration increases by 48 hours per slot level above 2nd."},{"id":"arcane_lock","level":2,"name":"Arcane Lock","nameEn":"Arcane Lock","school":"Abjuration","castingTime":"1 Action","range":"Touch","components":"V, S, M (gold dust worth at least 25 gp, consumed)","duration":"Until dispelled","concentration":false,"ritual":false,"description":"You touch a closed door, window, gate, chest, or other entryway, and it becomes locked for the duration. You and creatures you designate can open it normally; otherwise it is impassable until broken or until you cast knock on it. The DC to break or pick it increases by 10."},{"id":"arcane_vigor","level":2,"name":"Arcane Vigor","nameEn":"Arcane Vigor","school":"Abjuration","castingTime":"1 Bonus Action","range":"Self","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You tap into your life force to heal yourself. Roll one or two of your unexpended Hit Point Dice, and regain a number of Hit Points equal to the roll's total plus your spellcasting ability modifier. Those dice are then expended.\n\nUsing a Higher-Level Spell Slot. The number of unexpended Hit Dice you can roll increases by one for each spell slot level above 2."},{"id":"augury","level":2,"name":"Augury","nameEn":"Augury","school":"Divination","castingTime":"1 minute","range":"Self","components":"V, S, M (gem-inlaid sticks or similar tokens worth at least 25 gp)","duration":"Instantaneous","concentration":false,"ritual":true,"description":"By casting gem-inlaid sticks or other divining tools, you receive an omen about the results of a specific course of action you plan within the next 30 minutes: weal, woe, weal and woe, or nothing."},{"id":"barkskin","level":2,"name":"Barkskin","nameEn":"Barkskin","school":"Transmutation","castingTime":"1 Bonus Action","range":"Touch","components":"V, S, M (a handful of oak bark)","duration":"1 hour","concentration":false,"ritual":false,"description":"You touch a willing creature. Until the spell ends, its skin takes on a rough, bark-like appearance, and its AC can't be less than 16, regardless of what kind of armor it is wearing."},{"id":"beast_sense","level":2,"name":"Beast Sense","nameEn":"Beast Sense","school":"Divination","castingTime":"1 Action","range":"Touch","components":"S","duration":"Concentration, up to 1 hour","concentration":true,"ritual":true,"description":"You touch a willing beast. For the duration, you can use your action to see through the beast's eyes and hear what it hears, and continue to do so until you use your action to return to your normal senses."},{"id":"blindness_deafness","level":2,"name":"Blindness/Deafness","nameEn":"Blindness/Deafness","school":"Transmutation","castingTime":"1 Action","range":"120 feet","components":"V","duration":"1 minute","concentration":false,"ritual":false,"description":"You can blind or deafen a foe. One creature must succeed on a Constitution saving throw or be blinded or deafened (your choice) for the duration; it can repeat the save at the end of each of its turns. You can target additional creatures at higher levels."},{"id":"blur","level":2,"name":"Blur","nameEn":"Blur","school":"Illusion","castingTime":"1 Action","range":"Self","components":"V","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Your body becomes blurred and indistinct. For the duration, any creature has disadvantage on attack rolls against you. An attacker is immune if it doesn't rely on sight or can see through illusions."},{"id":"calm_emotions","level":2,"name":"Calm Emotions","nameEn":"Calm Emotions","school":"Enchantment","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You attempt to suppress strong emotions in a group. Each humanoid in a 20-foot-radius sphere within range must make a Charisma saving throw; on a failure you can suppress its charmed or frightened condition, or make it indifferent toward creatures it is hostile to."},{"id":"cloud_of_daggers","level":2,"name":"Cloud of Daggers","nameEn":"Cloud of Daggers","school":"Conjuration","castingTime":"1 Action","range":"60 feet","components":"V, S, M (a sliver of glass)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You fill the air with spinning daggers in a 5-foot cube centered on a point within range. A creature takes 4d4 slashing damage when it enters the area for the first time on a turn or starts its turn there. The damage increases by 2d4 per slot level above 2nd."},{"id":"continual_flame","level":2,"name":"Continual Flame","nameEn":"Continual Flame","school":"Evocation","castingTime":"1 Action","range":"Touch","components":"V, S, M (ruby dust worth 50 gp, consumed)","duration":"Until dispelled","concentration":false,"ritual":false,"description":"A flame, equivalent in brightness to a torch, springs forth from an object you touch. The effect looks like a regular flame but creates no heat and consumes no fuel. It can be covered or hidden but not smothered or quenched."},{"id":"cordon_of_arrows","level":2,"name":"Cordon of Arrows","nameEn":"Cordon of Arrows","school":"Transmutation","castingTime":"1 Action","range":"5 feet","components":"V, S, M (four or more arrows or bolts)","duration":"8 hours","concentration":false,"ritual":false,"description":"You plant four pieces of nonmagical ammunition in the ground and lay a ward. Until the spell ends, whenever a creature other than you comes within 30 feet of the arrows for the first time on a turn or ends its turn there, one arrow flies to attack it; the creature makes a Dexterity save or takes 1d6 piercing damage."},{"id":"crown_of_madness","level":2,"name":"Crown of Madness","nameEn":"Crown of Madness","school":"Enchantment","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"One humanoid you can see within range must succeed on a Wisdom saving throw or be charmed. While charmed, a jagged crown of energy appears on its head, and on each of its turns it must attack a creature you mentally choose. It can repeat the save at the end of its turns."},{"id":"darkness","level":2,"name":"Darkness","nameEn":"Darkness","school":"Evocation","castingTime":"1 Action","range":"60 feet","components":"V, M (bat fur and a drop of pitch or coal)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"Magical darkness spreads from a point within range to fill a 15-foot-radius sphere for the duration. The darkness spreads around corners and can't be penetrated by darkvision or nonmagical light. If cast on an object, the darkness moves with it."},{"id":"darkvision","level":2,"name":"Darkvision","nameEn":"Darkvision","school":"Transmutation","castingTime":"1 Action","range":"Touch","components":"V, S, M (dried carrot or agate)","duration":"8 hours","concentration":false,"ritual":false,"description":"You touch a willing creature to grant it the ability to see in the dark. For the duration, that creature has darkvision out to a range of 60 feet."},{"id":"detect_thoughts","level":2,"name":"Detect Thoughts","nameEn":"Detect Thoughts","school":"Divination","castingTime":"1 Action","range":"Self","components":"V, S, M (a copper coin)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"For the duration, you can read the surface thoughts of creatures within 30 feet. You can probe deeper into a creature's mind with a Wisdom saving throw, and you can search for thinking creatures you can't see."},{"id":"dragons_breath","level":2,"name":"Dragon's Breath","nameEn":"Dragon's Breath","school":"Transmutation","castingTime":"1 Bonus Action","range":"Touch","components":"V, S, M (a hot pepper)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You touch a willing creature, imbuing it with the power to spew elemental energy. Choose acid, cold, fire, lightning, or poison. Until the spell ends, the creature can use an action to exhale a 15-foot cone; each creature there makes a Dexterity save for 3d6 damage (half on success). The damage increases at higher levels."},{"id":"enhance_ability","level":2,"name":"Enhance Ability","nameEn":"Enhance Ability","school":"Transmutation","castingTime":"1 Action","range":"Touch","components":"V, S, M (fur or a feather from a beast)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You touch a creature and bestow a magical enhancement. Choose one effect (Bear's Endurance, Bull's Strength, Cat's Grace, Eagle's Splendor, Fox's Cunning, or Owl's Wisdom): the target gains advantage on checks with that ability, plus a related benefit. You can affect additional creatures at higher levels."},{"id":"enlarge_reduce","level":2,"name":"Enlarge/Reduce","nameEn":"Enlarge/Reduce","school":"Transmutation","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a pinch of powdered iron)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You cause a creature or object you can see to grow larger or smaller for the duration. Enlarge increases size by one category, granting advantage on Strength checks/saves and +1d4 weapon damage; Reduce does the opposite, imposing disadvantage and -1d4 damage."},{"id":"enthrall","level":2,"name":"Enthrall","nameEn":"Enthrall","school":"Enchantment","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You weave a distracting string of words. Each creature you choose within range must succeed on a Wisdom saving throw or have disadvantage on Perception checks made to perceive any creature other than you until the spell ends."},{"id":"find_steed","level":2,"name":"Find Steed","nameEn":"Find Steed","school":"Conjuration","castingTime":"1 Action","range":"30 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You summon a spirit that takes the form of a loyal steed (a warhorse, pony, camel, elk, or mastiff) with the celestial, fey, or fiend type. It serves as a mount and shares an intelligent bond with you, and while mounted you can make any spell that targets only you also target it."},{"id":"find_traps","level":2,"name":"Find Traps","nameEn":"Find Traps","school":"Divination","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You sense the presence of any trap within range that is within line of sight. You learn that at least one trap is present but not its location or nature."},{"id":"flame_blade","level":2,"name":"Flame Blade","nameEn":"Flame Blade","school":"Evocation","castingTime":"1 Bonus Action","range":"Self","components":"V, S, M (leaf of sumac)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You evoke a fiery blade in your free hand. You can make melee spell attacks with it for 3d6 fire damage on a hit, and it sheds bright light in a 10-foot radius. The damage increases by 1d6 per two slot levels above 2nd."},{"id":"flaming_sphere","level":2,"name":"Flaming Sphere","nameEn":"Flaming Sphere","school":"Conjuration","castingTime":"1 Action","range":"60 feet","components":"V, S, M (tallow, brimstone, and powdered iron)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"A 5-foot-diameter sphere of fire appears within range. Any creature that ends its turn within 5 feet makes a Dexterity save for 2d6 fire damage (half on success). As a bonus action you can move it 30 feet, ramming a creature for the same effect. The damage increases at higher levels."},{"id":"gentle_repose","level":2,"name":"Gentle Repose","nameEn":"Gentle Repose","school":"Necromancy","castingTime":"1 Action","range":"Touch","components":"V, S, M (a pinch of salt and a copper piece on each eye, consumed)","duration":"10 days","concentration":false,"ritual":true,"description":"You touch a corpse or other remains. For the duration, the target is protected from decay and can't become undead. The spell also extends the time limit for raising the target from the dead, since days spent under its effect don't count against that limit."},{"id":"gust_of_wind","level":2,"name":"Gust of Wind","nameEn":"Gust of Wind","school":"Evocation","castingTime":"1 Action","range":"Self (60-foot line)","components":"V, S, M (a legume seed)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"A line of strong wind 60 feet long and 10 feet wide blasts from you. Each creature in the line must succeed on a Strength saving throw or be pushed 15 feet away from you. The line is difficult terrain for creatures moving toward you, and the wind disperses gases and extinguishes small flames."},{"id":"heat_metal","level":2,"name":"Heat Metal","nameEn":"Heat Metal","school":"Transmutation","castingTime":"1 Action","range":"60 feet","components":"V, S, M (a piece of iron and a flame)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Choose a manufactured metal object you can see within range. It glows red-hot; any creature in contact takes 2d8 fire damage when you cast and each turn you use a bonus action to repeat. A creature holding it must succeed on a Constitution save or drop it. The damage increases at higher levels."},{"id":"hold_person","level":2,"name":"Hold Person","nameEn":"Hold Person","school":"Enchantment","castingTime":"1 Action","range":"60 feet","components":"V, S, M (a small straight piece of iron)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Choose a humanoid you can see within range. It must succeed on a Wisdom saving throw or be paralyzed for the duration, repeating the save at the end of each of its turns. You can target additional humanoids at higher levels."},{"id":"invisibility","level":2,"name":"Invisibility","nameEn":"Invisibility","school":"Illusion","castingTime":"1 Action","range":"Touch","components":"V, S, M (an eyelash encased in gum arabic)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"A creature you touch becomes invisible until the spell ends. Anything it is wearing or carrying is invisible as long as it is on the target's person. The spell ends if the target attacks or casts a spell. You can affect additional creatures at higher levels."},{"id":"knock","level":2,"name":"Knock","nameEn":"Knock","school":"Transmutation","castingTime":"1 Action","range":"60 feet","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"Choose an object that is locked, stuck, or barred within range. The object is unlocked, unstuck, or unbarred, and any nonmagical lock or arcane lock on it is suppressed. The spell produces a loud knock audible up to 300 feet away."},{"id":"lesser_restoration","level":2,"name":"Lesser Restoration","nameEn":"Lesser Restoration","school":"Abjuration","castingTime":"1 Bonus Action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You touch a creature and can end one disease or one condition afflicting it: blinded, deafened, paralyzed, or poisoned."},{"id":"levitate","level":2,"name":"Levitate","nameEn":"Levitate","school":"Transmutation","castingTime":"1 Action","range":"60 feet","components":"V, S, M (a small leather loop or golden wire bent into a cup)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"One creature or loose object of your choice rises vertically, up to 20 feet, and remains suspended for the duration. An unwilling creature can resist with a Constitution saving throw. You can move it up or down as part of your action."},{"id":"locate_animals_or_plants","level":2,"name":"Locate Animals or Plants","nameEn":"Locate Animals or Plants","school":"Divination","castingTime":"1 Action","range":"Self","components":"V, S, M (a bit of fur from a bloodhound)","duration":"Instantaneous","concentration":false,"ritual":true,"description":"Name or describe a specific kind of beast or plant. You learn the direction and distance to the closest creature or plant of that kind within 5 miles, if any are present."},{"id":"locate_object","level":2,"name":"Locate Object","nameEn":"Locate Object","school":"Divination","castingTime":"1 Action","range":"Self","components":"V, S, M (a forked twig)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"Describe or name an object familiar to you. You sense the direction to it as long as it is within 1,000 feet. The spell can't locate an object if any thickness of lead blocks a direct path between you and it."},{"id":"magic_mouth","level":2,"name":"Magic Mouth","nameEn":"Magic Mouth","school":"Illusion","castingTime":"1 minute","range":"30 feet","components":"V, S, M (a small bit of honeycomb and jade dust worth 10 gp, consumed)","duration":"Until dispelled","concentration":false,"ritual":true,"description":"You implant a message in an object that is triggered by a condition you specify. When the trigger occurs, a magical mouth appears and speaks the message (up to 25 words) in the voice and manner you specified."},{"id":"magic_weapon","level":2,"name":"Magic Weapon","nameEn":"Magic Weapon","school":"Transmutation","castingTime":"1 Bonus Action","range":"Touch","components":"V, S","duration":"1 hour","concentration":false,"ritual":false,"description":"You touch a nonmagical weapon. Until the spell ends, it becomes a magic weapon with a +1 bonus to attack and damage rolls. The bonus increases to +2 at 4th level and +3 at 6th level."},{"id":"melfs_acid_arrow","level":2,"name":"Melf's Acid Arrow","nameEn":"Melf's Acid Arrow","school":"Evocation","castingTime":"1 Action","range":"90 feet","components":"V, S, M (powdered rhubarb leaf and an adder's stomach)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A shimmering green arrow streaks toward a target. Make a ranged spell attack; on a hit it takes 4d4 acid damage immediately and 2d4 at the end of its next turn. On a miss it takes half the initial damage and none later. The damage increases at higher levels."},{"id":"mind_spike","level":2,"name":"Mind Spike","nameEn":"Mind Spike","school":"Divination","castingTime":"1 Action","range":"120 feet","components":"S","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You drive a spike of psionic energy into the mind of one creature you can see within range. The target makes a Wisdom saving throw, taking 3d8 Psychic damage on a failed save or half as much damage on a successful one.\n\nOn a failed save, you also always know the target's location until the spell ends, but only while the two of you are on the same plane of existence. While you have this knowledge, the target can't become hidden from you, and if it has the Invisible condition, it gains no benefit from that condition against you.\n\nUsing a Higher-Level Spell Slot. The damage increases by 1d8 for each spell slot level above 2."},{"id":"mirror_image","level":2,"name":"Mirror Image","nameEn":"Mirror Image","school":"Illusion","castingTime":"1 Action","range":"Self","components":"V, S","duration":"1 minute","concentration":false,"ritual":false,"description":"Three illusory duplicates of yourself appear in your space. Until the spell ends, the duplicates move with you and mimic your actions. Each time a creature targets you with an attack, roll to see whether it hits a duplicate instead; a hit duplicate is destroyed."},{"id":"misty_step","level":2,"name":"Misty Step","nameEn":"Misty Step","school":"Conjuration","castingTime":"1 Bonus Action","range":"Self","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space that you can see."},{"id":"moonbeam","level":2,"name":"Moonbeam","nameEn":"Moonbeam","school":"Evocation","castingTime":"1 Action","range":"120 feet","components":"V, S, M (several seeds of any moonseed plant and a piece of opalescent feldspar)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"A silvery beam of pale light shines down in a 5-foot-radius, 40-foot-high cylinder. A creature there when you cast it or that enters or ends its turn there makes a Constitution save for 2d10 radiant damage (half on success). As an action you can move the beam 60 feet. The damage increases at higher levels."},{"id":"nystuls_magic_aura","level":2,"name":"Nystul's Magic Aura","nameEn":"Nystul's Magic Aura","school":"Illusion","castingTime":"1 Action","range":"Touch","components":"V, S, M (a small square of silk)","duration":"24 hours","concentration":false,"ritual":false,"description":"With a touch, you place an illusion on a willing creature or an object that isn't being worn or carried. A creature gains the Mask effect below, and an object gains the False Aura effect below. The effect lasts for the duration. If you cast the spell on the same target every day for 30 days, the illusion lasts until dispelled.\n\nMask (Creature). Choose a creature type other than the target's actual type. Spells and other magical effects treat the target as if it were a creature of the chosen type.\n\nFalse Aura (Object). You change the way the target appears to spells and magical effects that detect magical auras, such as Detect Magic. You can make a nonmagical object appear magical, make a magic item appear nonmagical, or change the object's aura so that it appears to belong to a school of magic you choose."},{"id":"pass_without_trace","level":2,"name":"Pass without Trace","nameEn":"Pass without Trace","school":"Abjuration","castingTime":"1 Action","range":"Self","components":"V, S, M (ashes from a burned leaf of mistletoe and a sprig of spruce)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"A veil of shadows and silence radiates from you, masking you and your companions. For the duration, each creature you choose within 30 feet has a +10 bonus to Stealth checks and can't be tracked except by magical means."},{"id":"phantasmal_force","level":2,"name":"Phantasmal Force","nameEn":"Phantasmal Force","school":"Illusion","castingTime":"1 Action","range":"60 feet","components":"V, S, M (a bit of fleece)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You craft an illusion in the mind of a creature that fails an Intelligence saving throw. You create the image of an object, creature, or phenomenon no larger than a 10-foot cube that only the target perceives; the target rationalizes it as real and can take 1d6 psychic damage from it each turn."},{"id":"prayer_of_healing","level":2,"name":"Prayer of Healing","nameEn":"Prayer of Healing","school":"Abjuration","castingTime":"10 minutes","range":"30 feet","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"Up to six creatures of your choice within range each regain hit points equal to 2d8 + your spellcasting ability modifier. This spell has no effect on undead or constructs. The healing increases by 1d8 per slot level above 2nd."},{"id":"protection_from_poison","level":2,"name":"Protection from Poison","nameEn":"Protection from Poison","school":"Abjuration","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"1 hour","concentration":false,"ritual":false,"description":"You touch a creature. If it is poisoned, you neutralize the poison; if more than one poison afflicts it, you neutralize one. For the duration, the target has advantage on saving throws against being poisoned and resistance to poison damage."},{"id":"ray_of_enfeeblement","level":2,"name":"Ray of Enfeeblement","nameEn":"Ray of Enfeeblement","school":"Necromancy","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"A black beam of enervating energy springs from your finger. Make a ranged spell attack; on a hit the target deals only half damage with weapon attacks that use Strength until the spell ends. The target can repeat a Constitution save at the end of each of its turns to end the effect."},{"id":"rope_trick","level":2,"name":"Rope Trick","nameEn":"Rope Trick","school":"Transmutation","castingTime":"1 Action","range":"Touch","components":"V, S, M (powdered corn and a 6-inch loop of parchment)","duration":"1 hour","concentration":false,"ritual":false,"description":"You touch a length of rope up to 60 feet long. One end rises into the air until the whole rope hangs perpendicular to the ground, and an invisible extradimensional space opens at the upper end where up to eight creatures can climb to hide."},{"id":"scorching_ray","level":2,"name":"Scorching Ray","nameEn":"Scorching Ray","school":"Evocation","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You create three rays of fire and hurl them at targets within range. Make a ranged spell attack for each ray; on a hit a target takes 2d6 fire damage. You create one additional ray per slot level above 2nd."},{"id":"see_invisibility","level":2,"name":"See Invisibility","nameEn":"See Invisibility","school":"Divination","castingTime":"1 Action","range":"Self","components":"V, S, M (a pinch of talc and a small sprinkling of powdered silver)","duration":"1 hour","concentration":false,"ritual":false,"description":"For the duration, you can see invisible creatures and objects as if they were visible, and you can see into the Ethereal Plane, where such things appear ghostly."},{"id":"shatter","level":2,"name":"Shatter","nameEn":"Shatter","school":"Evocation","castingTime":"1 Action","range":"60 feet","components":"V, S, M (a chip of mica)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A sudden loud ringing noise erupts from a point of your choice. Each creature in a 10-foot-radius sphere must make a Constitution saving throw, taking 3d8 thunder damage on a failure or half on a success. Constructs have disadvantage. The damage increases by 1d8 per slot level above 2nd."},{"id":"shining_smite","level":2,"name":"Shining Smite","nameEn":"Shining Smite","school":"Transmutation","castingTime":"1 Bonus Action, which you take immediately after hitting a creature with a Melee weapon or an Unarmed Strike","range":"Self","components":"V","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"The target hit by the strike takes an extra 2d6 Radiant damage from the attack. Until the spell ends, the target sheds Bright Light in a 5-foot radius, attack rolls against it have Advantage, and it can't benefit from the Invisible condition.\n\nUsing a Higher-Level Spell Slot. The damage increases by 1d6 for each spell slot level above 2."},{"id":"silence","level":2,"name":"Silence","nameEn":"Silence","school":"Illusion","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":true,"description":"For the duration, no sound can be created within or pass through a 20-foot-radius sphere centered on a point within range. Creatures and objects there are immune to thunder damage, and creatures there are deafened. Verbal spells can't be cast in the area."},{"id":"spider_climb","level":2,"name":"Spider Climb","nameEn":"Spider Climb","school":"Transmutation","castingTime":"1 Action","range":"Touch","components":"V, S, M (a drop of bitumen and a spider)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"Until the spell ends, one willing creature you touch gains the ability to move up, down, and across vertical surfaces and ceilings while leaving its hands free, and gains a climbing speed equal to its walking speed."},{"id":"spike_growth","level":2,"name":"Spike Growth","nameEn":"Spike Growth","school":"Transmutation","castingTime":"1 Action","range":"150 feet","components":"V, S, M (seven sharp thorns or seven small twigs)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"The ground in a 20-foot radius within range twists with hard spikes and thorns, becoming difficult terrain. A creature takes 2d4 piercing damage for every 5 feet it travels there, and the area is camouflaged to look natural (Perception check to spot)."},{"id":"spiritual_weapon","level":2,"name":"Spiritual Weapon","nameEn":"Spiritual Weapon","school":"Evocation","castingTime":"1 Bonus Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You create a floating, spectral weapon within range that lasts for the duration. You can make a melee spell attack with it for 1d8 + your spellcasting modifier force damage. As a bonus action you can move it up to 20 feet and attack again. The damage increases by 1d8 per two slot levels above 2nd."},{"id":"suggestion","level":2,"name":"Suggestion","nameEn":"Suggestion","school":"Enchantment","castingTime":"1 Action","range":"30 feet","components":"V, M (a snake's tongue and a honeycomb or sweet oil)","duration":"Concentration, up to 8 hours","concentration":true,"ritual":false,"description":"You suggest a course of activity (limited to a sentence or two) to a creature that can hear and understand you. It must succeed on a Wisdom saving throw or pursue the suggested course as best it can, as long as the suggestion sounds reasonable."},{"id":"summon_beast","level":2,"name":"Summon Beast","nameEn":"Summon Beast","school":"Conjuration","castingTime":"1 Action","range":"90 feet","components":"V, S, M (a feather, tuft of fur, and fish tail in a gilded box worth 200 gp)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You call forth a bestial spirit that appears in an unoccupied space you can see. Choose its form: Air, Land, or Water. It is friendly to you and your companions, acts on your turn, and fights as you direct it."},{"id":"warding_bond","level":2,"name":"Warding Bond","nameEn":"Warding Bond","school":"Abjuration","castingTime":"1 Action","range":"Touch","components":"V, S, M (a pair of platinum rings worth at least 50 gp each, worn by you and the target)","duration":"1 hour","concentration":false,"ritual":false,"description":"You create a protective bond with a willing creature within touch. While it is within 60 feet, it gains a +1 bonus to AC and saves and resistance to all damage, but you take the same amount of damage it takes whenever it is harmed."},{"id":"web","level":2,"name":"Web","nameEn":"Web","school":"Conjuration","castingTime":"1 Action","range":"60 feet","components":"V, S, M (a bit of spiderweb)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You conjure thick, sticky webbing filling a 20-foot cube within range. The webs are difficult terrain and lightly obscure the area. A creature that enters or starts its turn there must succeed on a Dexterity saving throw or be restrained until it breaks free."},{"id":"zone_of_truth","level":2,"name":"Zone of Truth","nameEn":"Zone of Truth","school":"Enchantment","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"10 minutes","concentration":false,"ritual":false,"description":"You create a magical zone in a 15-foot-radius sphere within range. A creature that enters or starts its turn there must succeed on a Charisma saving throw or be unable to speak a deliberate lie while in the zone; it knows it is affected, but you don't know who failed."},{"id":"animate_dead","level":3,"name":"Animate Dead","nameEn":"Animate Dead","school":"Necromancy","castingTime":"1 minute","range":"10 feet","components":"V, S, M (a drop of blood, a piece of flesh, and a pinch of bone dust)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You create an undead servant from a pile of bones or a corpse within range, raising a skeleton or zombie under your control. You can command it mentally; reasserting control within 24 hours via this spell lets you maintain or create more. At higher levels you animate additional undead."},{"id":"aura_of_vitality","level":3,"name":"Aura of Vitality","nameEn":"Aura of Vitality","school":"Abjuration","castingTime":"1 Action","range":"Self (30-foot radius)","components":"V","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Healing energy radiates from you in a 30-foot aura. Until the spell ends, the aura moves with you, and you can use a bonus action to cause one creature in it (including you) to regain 2d6 hit points."},{"id":"beacon_of_hope","level":3,"name":"Beacon of Hope","nameEn":"Beacon of Hope","school":"Abjuration","castingTime":"1 Action","range":"30 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You bestow hope and vitality on any number of creatures within range. For the duration, each target has advantage on Wisdom saving throws and death saving throws, and regains the maximum number of hit points possible from any healing."},{"id":"bestow_curse","level":3,"name":"Bestow Curse","nameEn":"Bestow Curse","school":"Necromancy","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You touch a creature, which must succeed on a Wisdom saving throw or be cursed. Choose one effect: disadvantage on checks and saves with one ability; disadvantage on attacks against you; it must save each turn or waste its action; or you deal an extra 1d8 necrotic damage to it. The duration lengthens at higher levels."},{"id":"blinding_smite","level":3,"name":"Blinding Smite","nameEn":"Blinding Smite","school":"Evocation","castingTime":"1 Bonus Action","range":"Self","components":"V","duration":"1 minute","concentration":false,"ritual":false,"description":"The next time you hit a creature with a melee weapon attack before the spell ends, it flares with light, dealing an extra 3d8 radiant damage. The target must succeed on a Constitution saving throw or be blinded until the spell ends, repeating the save at the end of each of its turns."},{"id":"blink","level":3,"name":"Blink","nameEn":"Blink","school":"Transmutation","castingTime":"1 Action","range":"Self","components":"V, S","duration":"1 minute","concentration":false,"ritual":false,"description":"At the end of each of your turns for the duration, roll a d20: on an 11 or higher you vanish into the Ethereal Plane, then return at the start of your next turn to an unoccupied space within 10 feet. While ethereal, you can't be affected by anything on the Material Plane."},{"id":"call_lightning","level":3,"name":"Call Lightning","nameEn":"Call Lightning","school":"Conjuration","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"A storm cloud appears within range above you. When you cast and as an action on later turns, you call a bolt to a point under the cloud; each creature within 5 feet of that point makes a Dexterity save for 3d10 lightning damage (half on success). Outdoors in a storm it deals 4d10. The damage increases at higher levels."},{"id":"clairvoyance","level":3,"name":"Clairvoyance","nameEn":"Clairvoyance","school":"Divination","castingTime":"10 minutes","range":"1 mile","components":"V, S, M (a focus worth at least 100 gp: a jeweled horn for hearing or a glass eye for seeing)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You create an invisible sensor within range in a location familiar to you or an obvious one. Choose seeing or hearing when you cast it; you can use your action to perceive through the sensor as though you were there."},{"id":"conjure_animals","level":3,"name":"Conjure Animals","nameEn":"Conjure Animals","school":"Conjuration","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You summon fey spirits that take the form of beasts and appear in unoccupied spaces within range. You choose one beast of CR 2 or several lower-CR beasts. The summoned creatures are friendly to you, act on your turn, and obey your verbal commands. More appear at higher levels."},{"id":"conjure_barrage","level":3,"name":"Conjure Barrage","nameEn":"Conjure Barrage","school":"Conjuration","castingTime":"1 Action","range":"Self (60-foot cone)","components":"V, S, M (one piece of ammunition or a thrown weapon)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You throw a weapon or fire ammunition into the air to create a cone of identical weapons. Each creature in a 60-foot cone must make a Dexterity saving throw, taking 3d8 damage of the weapon's type on a failure or half on a success."},{"id":"counterspell","level":3,"name":"Counterspell","nameEn":"Counterspell","school":"Abjuration","castingTime":"1 Reaction","range":"60 feet","components":"S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You attempt to interrupt a creature casting a spell within range. If it is casting a spell of 3rd level or lower, the spell fails automatically; if higher, make an ability check using your spellcasting ability (DC 10 + the spell's level) to negate it. Cast at higher levels to auto-counter higher-level spells."},{"id":"create_food_and_water","level":3,"name":"Create Food and Water","nameEn":"Create Food and Water","school":"Conjuration","castingTime":"1 Action","range":"30 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You create 45 pounds of food and 30 gallons of water on the ground or in containers within range, enough to sustain up to fifteen humanoids or five steeds for 24 hours. The food is bland but nourishing and spoils after 24 hours."},{"id":"crusaders_mantle","level":3,"name":"Crusader's Mantle","nameEn":"Crusader's Mantle","school":"Evocation","castingTime":"1 Action","range":"Self (30-foot radius)","components":"V","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Holy power radiates from you in a 30-foot aura that moves with you. Until the spell ends, each creature of your choice in the aura (including you) deals an extra 1d4 radiant damage when it hits with a weapon attack."},{"id":"daylight","level":3,"name":"Daylight","nameEn":"Daylight","school":"Evocation","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"1 hour","concentration":false,"ritual":false,"description":"A 60-foot-radius sphere of bright light (plus 60 feet of dim light) springs from a point or an object you choose. The light is sunlight, and if any of it overlaps with magical darkness created by a spell of 3rd level or lower, that darkness is dispelled."},{"id":"dispel_magic","level":3,"name":"Dispel Magic","nameEn":"Dispel Magic","school":"Abjuration","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"Choose a creature, object, or magical effect within range. Any spell of 3rd level or lower on the target ends. For each spell of 4th level or higher, make an ability check using your spellcasting ability (DC 10 + the spell's level) to end it. Cast at higher levels to automatically end higher-level spells."},{"id":"elemental_weapon","level":3,"name":"Elemental Weapon","nameEn":"Elemental Weapon","school":"Transmutation","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"A nonmagical weapon you touch becomes magical. Choose acid, cold, fire, lightning, or thunder; for the duration the weapon has a +1 bonus to attack rolls and deals an extra 1d4 damage of the chosen type. The bonuses increase at higher levels."},{"id":"fear","level":3,"name":"Fear","nameEn":"Fear","school":"Illusion","castingTime":"1 Action","range":"Self (30-foot cone)","components":"V, S, M (a white feather or the heart of a hen)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You project a phantasmal image in a 30-foot cone. Each creature there must succeed on a Wisdom saving throw or drop whatever it is holding and become frightened, fleeing from you on its turns until it can no longer see you. It can repeat the save at the end of its turns."},{"id":"feign_death","level":3,"name":"Feign Death","nameEn":"Feign Death","school":"Necromancy","castingTime":"1 Action","range":"Touch","components":"V, S, M (a pinch of graveyard dirt)","duration":"1 hour","concentration":false,"ritual":true,"description":"You touch a willing creature and put it into a cataleptic state indistinguishable from death. For the duration the target appears dead, is blinded and incapacitated, has resistance to all damage except psychic, and any disease or poison is suspended."},{"id":"fireball","level":3,"name":"Fireball","nameEn":"Fireball","school":"Evocation","castingTime":"1 Action","range":"150 feet","components":"V, S, M (a tiny ball of bat guano and sulfur)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A bright streak flashes to a point within range and blossoms into a fiery explosion. Each creature in a 20-foot-radius sphere must make a Dexterity saving throw, taking 8d6 fire damage on a failure or half on a success. Flammable objects in the area ignite. The damage increases by 1d6 per slot level above 3rd."},{"id":"fly","level":3,"name":"Fly","nameEn":"Fly","school":"Transmutation","castingTime":"1 Action","range":"Touch","components":"V, S, M (a wing feather from any bird)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You touch a willing creature, granting it a flying speed of 60 feet for the duration. When the spell ends, the target falls if it is still aloft. You can affect additional creatures at higher levels."},{"id":"gaseous_form","level":3,"name":"Gaseous Form","nameEn":"Gaseous Form","school":"Transmutation","castingTime":"1 Action","range":"Touch","components":"V, S, M (a bit of gauze and a wisp of smoke)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You transform a willing creature you touch, along with everything it is wearing and carrying, into a misty cloud for the duration. It has resistance to nonmagical damage, can pass through small holes and cracks, but can't attack, cast spells, or manipulate objects, and has a flying speed of 10 feet."},{"id":"glyph_of_warding","level":3,"name":"Glyph of Warding","nameEn":"Glyph of Warding","school":"Abjuration","castingTime":"1 hour","range":"Touch","components":"V, S, M (incense and powdered diamond worth at least 200 gp, consumed)","duration":"Until dispelled or triggered","concentration":false,"ritual":false,"description":"You inscribe a glyph that harms others when triggered by a condition you set. Choose an explosive rune (up to 5d8 damage of a chosen type in a 20-foot radius) or a spell glyph (store a prepared spell of 3rd level or lower). The damage and storable spell level increase at higher levels."},{"id":"haste","level":3,"name":"Haste","nameEn":"Haste","school":"Transmutation","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a shaving of licorice root)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Choose a willing creature you can see. Until the spell ends, its speed is doubled, it gains +2 AC and advantage on Dexterity saves, and an additional action each turn (to Attack once, Dash, Disengage, Hide, or Use an Object). When the spell ends, the target can't move or take actions until the end of its next turn."},{"id":"hunger_of_hadar","level":3,"name":"Hunger of Hadar","nameEn":"Hunger of Hadar","school":"Conjuration","castingTime":"1 Action","range":"150 feet","components":"V, S, M (a pickled octopus tentacle)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You open a void in a 20-foot-radius sphere within range. The area is filled with darkness and the sound of the Far Realm. A creature that starts its turn there takes 2d6 cold damage; a creature that ends its turn there must make a Dexterity save or take 2d6 acid damage. The area is difficult terrain."},{"id":"hypnotic_pattern","level":3,"name":"Hypnotic Pattern","nameEn":"Hypnotic Pattern","school":"Illusion","castingTime":"1 Action","range":"120 feet","components":"S, M (a glowing stick of incense or a crystal vial of phosphorescent material)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You create a twisting pattern of colors in a 30-foot cube within range. Each creature there that sees it must succeed on a Wisdom saving throw or become charmed for the duration, becoming incapacitated and with a speed of 0. The effect ends for a creature if it takes damage or someone shakes it awake."},{"id":"leomunds_tiny_hut","level":3,"name":"Leomund's Tiny Hut","nameEn":"Leomund's Tiny Hut","school":"Evocation","castingTime":"1 minute or Ritual","range":"Self","components":"V, S, M (a crystal bead)","duration":"8 hours","concentration":false,"ritual":true,"description":"A 10-foot Emanation springs into existence around you and remains stationary for the duration. The spell fails when you cast it if the Emanation isn't big enough to fully encapsulate all creatures in its area.\n\nCreatures and objects within the Emanation when you cast the spell can move through it freely. All other creatures and objects are barred from passing through it. Spells of level 3 or lower can't be cast through it, and the effects of such spells can't extend into it.\n\nThe atmosphere inside the Emanation is comfortable and dry, regardless of the weather outside. Until the spell ends, you can command the interior to have Dim Light or Darkness (no action required). The Emanation is opaque from the outside and of any color you choose, but it's transparent from the inside.\n\nThe spell ends early if you leave the Emanation or if you cast it again."},{"id":"lightning_arrow","level":3,"name":"Lightning Arrow","nameEn":"Lightning Arrow","school":"Transmutation","castingTime":"1 Bonus Action","range":"Self","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"The next time you make a ranged weapon attack before the spell ends, the ammunition becomes a lightning bolt, dealing 4d8 lightning damage on a hit or 2d8 on a miss. Then each creature within 10 feet of the target makes a Dexterity save for 2d8 lightning damage (half on success). The damage increases at higher levels."},{"id":"lightning_bolt","level":3,"name":"Lightning Bolt","nameEn":"Lightning Bolt","school":"Evocation","castingTime":"1 Action","range":"Self (100-foot line)","components":"V, S, M (a bit of fur and a glass rod)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A stroke of lightning forming a line 100 feet long and 5 feet wide blasts out from you. Each creature in the line must make a Dexterity saving throw, taking 8d6 lightning damage on a failure or half on a success. The damage increases by 1d6 per slot level above 3rd."},{"id":"magic_circle","level":3,"name":"Magic Circle","nameEn":"Magic Circle","school":"Abjuration","castingTime":"1 minute","range":"10 feet","components":"V, S, M (holy water or powdered silver and iron worth at least 100 gp, consumed)","duration":"1 hour","concentration":false,"ritual":false,"description":"You create a 10-foot-radius, 20-foot-tall cylinder of magical energy. Choose one or more creature types (celestials, elementals, fey, fiends, or undead); they can't willingly enter the cylinder, have disadvantage on attacks against creatures inside, and can't charm, frighten, or possess them. You can invert it to trap creatures inside."},{"id":"major_image","level":3,"name":"Major Image","nameEn":"Major Image","school":"Illusion","castingTime":"1 Action","range":"120 feet","components":"V, S, M (a bit of fleece)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You create the image of an object, creature, or phenomenon no larger than a 20-foot cube, including sounds, smells, and temperature. You can move it as an action. Physical interaction reveals it as illusory, but an Investigation check against your save DC is needed to discern it by inspection."},{"id":"mass_healing_word","level":3,"name":"Mass Healing Word","nameEn":"Mass Healing Word","school":"Abjuration","castingTime":"1 Bonus Action","range":"60 feet","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"Up to six creatures of your choice that you can see within range each regain hit points equal to 1d4 + your spellcasting ability modifier. This spell has no effect on undead or constructs. The healing increases by 1d4 per slot level above 3rd."},{"id":"meld_into_stone","level":3,"name":"Meld into Stone","nameEn":"Meld into Stone","school":"Transmutation","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"8 hours","concentration":false,"ritual":true,"description":"You step into a stone object or surface large enough to fully contain your body, melding yourself and your gear with the stone. You can sense what happens around you and move within the stone, but can't see out and have disadvantage on Perception checks."},{"id":"nondetection","level":3,"name":"Nondetection","nameEn":"Nondetection","school":"Abjuration","castingTime":"1 Action","range":"Touch","components":"V, S, M (a pinch of diamond dust worth 25 gp, consumed)","duration":"8 hours","concentration":false,"ritual":false,"description":"For the duration, you hide a target you touch (a creature, place, or object no larger than 10 feet in any dimension) from divination magic. It can't be targeted by divination spells or perceived through magical scrying sensors."},{"id":"phantom_steed","level":3,"name":"Phantom Steed","nameEn":"Phantom Steed","school":"Illusion","castingTime":"1 minute","range":"30 feet","components":"V, S","duration":"1 hour","concentration":false,"ritual":true,"description":"A Large, quasi-real, horselike creature appears on the ground in an unoccupied space within range. It serves as a mount, has AC 13 and 1 hit point, and a speed of 100 feet. It can travel 10 miles in an hour (13 at a gallop). When the spell ends, the steed gradually fades."},{"id":"plant_growth","level":3,"name":"Plant Growth","nameEn":"Plant Growth","school":"Transmutation","castingTime":"1 Action or 8 hours","range":"150 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You channel vitality into plants. As an action, you enrich all plants in a 100-foot radius, making the area difficult terrain. Over 8 hours, you enrich the land in a half-mile radius so that crops there produce twice the normal yield for one year."},{"id":"protection_from_energy","level":3,"name":"Protection from Energy","nameEn":"Protection from Energy","school":"Abjuration","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"For the duration, a willing creature you touch has resistance to one damage type of your choice: acid, cold, fire, lightning, or thunder."},{"id":"remove_curse","level":3,"name":"Remove Curse","nameEn":"Remove Curse","school":"Abjuration","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"At your touch, all curses affecting one creature or object end. If the object is a cursed magic item, its curse remains, but you break the item's attunement to the creature so it can be removed or discarded."},{"id":"revivify","level":3,"name":"Revivify","nameEn":"Revivify","school":"Necromancy","castingTime":"1 Action","range":"Touch","components":"V, S, M (diamonds worth 300 gp, consumed)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You touch a creature that has died within the last minute. It returns to life with 1 hit point. This spell can't return to life a creature that has died of old age, nor can it restore missing body parts."},{"id":"sending","level":3,"name":"Sending","nameEn":"Sending","school":"Divination","castingTime":"1 Action","range":"Unlimited","components":"V, S, M (a short piece of fine copper wire)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You send a short message of 25 words or less to a creature you are familiar with. The creature hears the message in its mind, recognizes you, and can reply in kind immediately. You can send the message across any distance and even to other planes (with a chance of failure)."},{"id":"sleet_storm","level":3,"name":"Sleet Storm","nameEn":"Sleet Storm","school":"Conjuration","castingTime":"1 Action","range":"150 feet","components":"V, S, M (a pinch of dust and a few drops of water)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Freezing rain and sleet fall in a 40-foot-tall, 20-foot-radius cylinder. The area is heavily obscured, the ground is slick difficult terrain, and a creature there when you cast it (or that enters it) must succeed on a Dexterity save or fall prone. Concentration is broken if a caster is knocked prone there."},{"id":"slow","level":3,"name":"Slow","nameEn":"Slow","school":"Transmutation","castingTime":"1 Action","range":"120 feet","components":"V, S, M (a drop of molasses)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You alter time around up to six creatures in a 40-foot cube within range. Each must succeed on a Wisdom saving throw or be slowed: its speed is halved, it takes a -2 penalty to AC and Dexterity saves, can't use reactions, and is limited to a single action or bonus action each turn. It repeats the save each turn."},{"id":"speak_with_dead","level":3,"name":"Speak with Dead","nameEn":"Speak with Dead","school":"Necromancy","castingTime":"1 Action","range":"10 feet","components":"V, S, M (burning incense)","duration":"10 minutes","concentration":false,"ritual":false,"description":"You grant the semblance of life to a corpse within range that still has a mouth and hasn't been dead more than 10 days, allowing it to answer up to five questions. The corpse knows only what it knew in life, and can be evasive or brief."},{"id":"speak_with_plants","level":3,"name":"Speak with Plants","nameEn":"Speak with Plants","school":"Transmutation","castingTime":"1 Action","range":"Self (30-foot radius)","components":"V, S","duration":"10 minutes","concentration":false,"ritual":false,"description":"You imbue plants within 30 feet with limited sentience and animation, letting you question them about events in the area within the past day, and command them to move aside, free creatures, or make their area passable or difficult terrain."},{"id":"spirit_guardians","level":3,"name":"Spirit Guardians","nameEn":"Spirit Guardians","school":"Conjuration","castingTime":"1 Action","range":"Self (15-foot radius)","components":"V, S, M (a holy symbol)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You call forth protective spirits that flit around you in a 15-foot radius. They slow hostile creatures (speed halved in the area), and a creature that enters the area for the first time on a turn or starts there makes a Wisdom save for 3d8 radiant or necrotic damage (half on success). The damage increases at higher levels."},{"id":"stinking_cloud","level":3,"name":"Stinking Cloud","nameEn":"Stinking Cloud","school":"Conjuration","castingTime":"1 Action","range":"90 feet","components":"V, S, M (a rotten egg or several skunk cabbage leaves)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You create a 20-foot-radius sphere of yellow, nauseating gas centered on a point within range. The area is heavily obscured. A creature that starts its turn there must succeed on a Constitution saving throw or be unable to take anything but a move action that turn, retching and reeling."},{"id":"summon_fey","level":3,"name":"Summon Fey","nameEn":"Summon Fey","school":"Conjuration","castingTime":"1 Action","range":"90 feet","components":"V, S, M (a gilded flower worth 300+ GP)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You call forth a Fey spirit. It manifests in an unoccupied space that you can see within range and uses the Fey Spirit stat block. When you cast the spell, choose a mood: Fuming, Mirthful, or Tricksy. The creature resembles a Fey creature of your choice marked by the chosen mood, which determines certain details in its stat block.\n\nThe creature disappears when it drops to 0 Hit Points or when the spell ends. The creature is an ally to you and your allies. In combat, the creature shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger.\n\nUsing a Higher-Level Spell Slot. Use the spell slot's level for the spell's level in the stat block."},{"id":"summon_undead","level":3,"name":"Summon Undead","nameEn":"Summon Undead","school":"Necromancy","castingTime":"1 Action","range":"90 feet","components":"V, S, M (a gilded skull worth 300+ GP)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You call forth an Undead spirit. It manifests in an unoccupied space that you can see within range and uses the Undead Spirit stat block. When you cast the spell, choose the creature's form: Ghostly, Putrid, or Skeletal. The spirit resembles an Undead creature with the chosen form, which determines certain details in its stat block.\n\nThe creature disappears when it drops to 0 Hit Points or when the spell ends. The creature is an ally to you and your allies. In combat, the creature shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger.\n\nUsing a Higher-Level Spell Slot. Use the spell slot's level for the spell's level in the stat block."},{"id":"tongues","level":3,"name":"Tongues","nameEn":"Tongues","school":"Divination","castingTime":"1 Action","range":"Touch","components":"V, M (a small clay model of a ziggurat)","duration":"1 hour","concentration":false,"ritual":false,"description":"This spell grants the creature you touch the ability to understand any spoken language it hears. Moreover, when the target speaks, any creature that knows at least one language and can hear it understands what it says."},{"id":"vampiric_touch","level":3,"name":"Vampiric Touch","nameEn":"Vampiric Touch","school":"Necromancy","castingTime":"1 Action","range":"Self","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"The touch of your shadow-wreathed hand can siphon life. Make a melee spell attack against a creature within reach; on a hit it takes 3d6 necrotic damage, and you regain hit points equal to half the damage. Until the spell ends you can repeat the attack each turn. The damage increases at higher levels."},{"id":"water_breathing","level":3,"name":"Water Breathing","nameEn":"Water Breathing","school":"Transmutation","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a short reed or piece of straw)","duration":"24 hours","concentration":false,"ritual":true,"description":"This spell grants up to ten willing creatures you can see within range the ability to breathe underwater until the spell ends. Affected creatures also retain their normal mode of respiration."},{"id":"water_walk","level":3,"name":"Water Walk","nameEn":"Water Walk","school":"Transmutation","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a piece of cork)","duration":"1 hour","concentration":false,"ritual":true,"description":"This spell grants the ability to move across any liquid surface - water, acid, mud, snow, quicksand, or lava - as if it were harmless solid ground. Up to ten willing creatures you can see within range gain this ability for the duration."},{"id":"wind_wall","level":3,"name":"Wind Wall","nameEn":"Wind Wall","school":"Evocation","castingTime":"1 Action","range":"120 feet","components":"V, S, M (a tiny fan and a feather of exotic origin)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"A wall of strong wind up to 50 feet long, 15 feet high, and 1 foot thick rises from the ground within range. It deflects small flying creatures and objects, disperses gas, and a creature in its area makes a Strength save for 3d8 bludgeoning damage (half on success)."},{"id":"arcane_eye","level":4,"name":"Arcane Eye","nameEn":"Arcane Eye","school":"Divination","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a bit of bat fur)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You create an invisible, floating eye within range that sends you mental visual information. It has darkvision out to 30 feet and can see normally. As an action you can move it up to 30 feet in any direction, including through small openings, but not through solid matter."},{"id":"aura_of_life","level":4,"name":"Aura of Life","nameEn":"Aura of Life","school":"Abjuration","castingTime":"1 Action","range":"Self (30-foot radius)","components":"V","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"Life-preserving energy radiates from you in a 30-foot aura that moves with you. Each creature of your choice in the aura (including you) has resistance to necrotic damage, its hit point maximum can't be reduced, and a non-hostile creature at 0 hit points regains 1 hit point at the start of its turn."},{"id":"aura_of_purity","level":4,"name":"Aura of Purity","nameEn":"Aura of Purity","school":"Abjuration","castingTime":"1 Action","range":"Self (30-foot radius)","components":"V","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"Purifying energy radiates from you in a 30-foot aura that moves with you. Each creature of your choice in the aura (including you) can't be diseased, has resistance to poison damage, advantage on saves against effects that cause conditions, and immunity to being poisoned."},{"id":"banishment","level":4,"name":"Banishment","nameEn":"Banishment","school":"Abjuration","castingTime":"1 Action","range":"30 feet","components":"V, S, M (an item distasteful to the target)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You attempt to send one creature you can see to another plane of existence. It must succeed on a Charisma saving throw or be banished. If it is native to the plane you are on, it is banished to a harmless demiplane and returns when the spell ends; otherwise it is banished permanently if you concentrate for the full minute. You can target additional creatures at higher levels."},{"id":"blight","level":4,"name":"Blight","nameEn":"Blight","school":"Necromancy","castingTime":"1 Action","range":"30 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"Necromantic energy washes over a creature, draining moisture and vitality. It must make a Constitution saving throw, taking 8d8 necrotic damage on a failure or half on a success. Plant creatures have disadvantage and take maximum damage; a nonmagical plant withers. The damage increases by 1d8 per slot level above 4th."},{"id":"charm_monster","level":4,"name":"Charm Monster","nameEn":"Charm Monster","school":"Enchantment","castingTime":"1 Action","range":"30 feet","components":"V, S","duration":"1 hour","concentration":false,"ritual":false,"description":"One creature you can see within range makes a Wisdom saving throw. It does so with Advantage if you or your allies are fighting it. On a failed save, the target has the Charmed condition until the spell ends or until you or your allies damage it. The Charmed creature is Friendly to you. When the spell ends, the target knows it was Charmed by you.\n\nUsing a Higher-Level Spell Slot. You can target one additional creature for each spell slot level above 4."},{"id":"compulsion","level":4,"name":"Compulsion","nameEn":"Compulsion","school":"Enchantment","castingTime":"1 Action","range":"30 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Creatures of your choice within range must succeed on a Wisdom saving throw or be affected. Until the spell ends, on each of an affected creature's turns you can use a bonus action to designate a direction, and the creature must move in that direction (it doesn't move into obvious harm)."},{"id":"confusion","level":4,"name":"Confusion","nameEn":"Confusion","school":"Enchantment","castingTime":"1 Action","range":"90 feet","components":"V, S, M (three nut shells)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"This spell assaults the minds of creatures in a 10-foot-radius sphere. Each must succeed on a Wisdom saving throw or be unable to act normally: roll on a table each turn to determine whether it does nothing, moves randomly, attacks at random, or acts normally. A target can repeat the save each turn. The radius increases at higher levels."},{"id":"conjure_minor_elementals","level":4,"name":"Conjure Minor Elementals","nameEn":"Conjure Minor Elementals","school":"Conjuration","castingTime":"1 Action","range":"90 feet","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You summon elementals that appear in unoccupied spaces within range. You choose one elemental of CR 2 or several lower-CR elementals. They are friendly to you and your companions, act on your turn, and obey your verbal commands. More appear at higher levels."},{"id":"conjure_woodland_beings","level":4,"name":"Conjure Woodland Beings","nameEn":"Conjure Woodland Beings","school":"Conjuration","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You summon fey creatures that appear in unoccupied spaces within range. You choose one fey of CR 2 or several lower-CR fey. They are friendly to you and your companions, act on your turn, and obey your verbal commands. More appear at higher levels."},{"id":"control_water","level":4,"name":"Control Water","nameEn":"Control Water","school":"Transmutation","castingTime":"1 Action","range":"300 feet","components":"V, S, M (a drop of water and a pinch of dust)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You control water within an area within range. Choose an effect: rise it into a flood, part it to form a trench, redirect its flow, or create a whirlpool that pulls and damages creatures. The area can be up to 100 feet on a side."},{"id":"death_ward","level":4,"name":"Death Ward","nameEn":"Death Ward","school":"Abjuration","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"8 hours","concentration":false,"ritual":false,"description":"You touch a creature and grant it a measure of protection from death. The first time the target would drop to 0 hit points before the spell ends, it instead drops to 1 hit point. If an effect would kill it instantly without dealing damage, that effect is negated. The spell then ends."},{"id":"dimension_door","level":4,"name":"Dimension Door","nameEn":"Dimension Door","school":"Conjuration","castingTime":"1 Action","range":"500 feet","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You teleport yourself from your current location to any spot within range that you can see, visualize, or describe by stating distance and direction. You can bring one willing creature within 5 feet of you. If you would arrive in occupied space, you and any companion each take 4d6 force damage and the teleport fails."},{"id":"divination","level":4,"name":"Divination","nameEn":"Divination","school":"Divination","castingTime":"1 Action","range":"Self","components":"V, S, M (incense and a sacrificial offering worth at least 25 gp, consumed)","duration":"Instantaneous","concentration":false,"ritual":true,"description":"Your magic and an offering put you in contact with a god or its servants. You ask a single question about a specific goal, event, or activity within 7 days, and receive a truthful reply, usually a short phrase, cryptic rhyme, or omen."},{"id":"dominate_beast","level":4,"name":"Dominate Beast","nameEn":"Dominate Beast","school":"Enchantment","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You attempt to beguile a beast you can see within range. It must succeed on a Wisdom saving throw or be charmed for the duration, establishing a telepathic link through which you can command it. You can take total control as an action; the target repeats the save each time it takes damage. The duration lengthens at higher levels."},{"id":"evards_black_tentacles","level":4,"name":"Evard's Black Tentacles","nameEn":"Evard's Black Tentacles","school":"Conjuration","castingTime":"1 Action","range":"90 feet","components":"V, S, M (a piece of tentacle from a giant octopus or squid)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Squirming, ebony tentacles fill a 20-foot square within range, turning it into difficult terrain. A creature there when you cast it or that enters or starts its turn there makes a Dexterity save or takes 3d6 bludgeoning damage and is restrained; a restrained creature can use its action to try to break free."},{"id":"fabricate","level":4,"name":"Fabricate","nameEn":"Fabricate","school":"Transmutation","castingTime":"10 minutes","range":"120 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You convert raw materials into products of the same material: create a large or several small objects from wood, stone, metal, or other matter. The quality matches your skill with the appropriate tools. You can't create or transform creatures or magic items."},{"id":"fire_shield","level":4,"name":"Fire Shield","nameEn":"Fire Shield","school":"Evocation","castingTime":"1 Action","range":"Self","components":"V, S, M (a bit of phosphorus or a firefly)","duration":"10 minutes","concentration":false,"ritual":false,"description":"Thin flames wreathe your body, shedding light. Choose a warm shield (resistance to cold damage) or a chill shield (resistance to fire damage). Until the spell ends, a creature within 5 feet that hits you with a melee attack takes 2d8 fire or cold damage."},{"id":"fount_of_moonlight","level":4,"name":"Fount of Moonlight","nameEn":"Fount of Moonlight","school":"Evocation","castingTime":"1 Action","range":"Self","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"A cool light wreathes your body for the duration, emitting Bright Light in a 20-foot radius and Dim Light for an additional 20 feet.\n\nUntil the spell ends, you have Resistance to Radiant damage, and your melee attacks deal an extra 2d6 Radiant damage on a hit.\n\nIn addition, immediately after you take damage from a creature you can see within 60 feet of yourself, you can take a Reaction to force the creature to make a Constitution saving throw. On a failed save, the creature has the Blinded condition until the end of your next turn."},{"id":"freedom_of_movement","level":4,"name":"Freedom of Movement","nameEn":"Freedom of Movement","school":"Abjuration","castingTime":"1 Action","range":"Touch","components":"V, S, M (a leather strap bound around the arm or a similar appendage)","duration":"1 hour","concentration":false,"ritual":false,"description":"You touch a willing creature. For the duration, its movement is unaffected by difficult terrain, and spells and effects can't reduce its speed or cause it to be paralyzed or restrained. It can also spend 5 feet of movement to escape nonmagical restraints or grapples."},{"id":"giant_insect","level":4,"name":"Giant Insect","nameEn":"Giant Insect","school":"Conjuration","castingTime":"1 Action","range":"30 feet","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You transform up to ten centipedes, three spiders, five wasps, or a scorpion within range into giant versions of their natural forms. They obey your verbal commands and act on your turn, attacking your enemies as you direct."},{"id":"grasping_vine","level":4,"name":"Grasping Vine","nameEn":"Grasping Vine","school":"Conjuration","castingTime":"1 Bonus Action","range":"30 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You conjure a vine that sprouts from the ground in an unoccupied space within range. When you cast it and as a bonus action on later turns, you can direct it to lash at one creature within 30 feet of it; that creature must succeed on a Dexterity saving throw or be pulled up to 20 feet toward the vine."},{"id":"greater_invisibility","level":4,"name":"Greater Invisibility","nameEn":"Greater Invisibility","school":"Illusion","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You or a creature you touch becomes invisible until the spell ends. Anything the target is wearing or carrying is invisible as long as it is on the target's person. Unlike lesser invisibility, the effect persists even if the target attacks or casts a spell."},{"id":"guardian_of_faith","level":4,"name":"Guardian of Faith","nameEn":"Guardian of Faith","school":"Conjuration","castingTime":"1 Action","range":"30 feet","components":"V","duration":"8 hours","concentration":false,"ritual":false,"description":"A Large spectral guardian appears in an unoccupied space within range and hovers for the duration. Any creature hostile to you that moves to within 10 feet for the first time on a turn must succeed on a Dexterity saving throw or take 20 radiant damage. The guardian vanishes after dealing a total of 60 damage."},{"id":"hallucinatory_terrain","level":4,"name":"Hallucinatory Terrain","nameEn":"Hallucinatory Terrain","school":"Illusion","castingTime":"10 minutes","range":"300 feet","components":"V, S, M (a stone, a twig, and a bit of green plant)","duration":"24 hours","concentration":false,"ritual":false,"description":"You make natural terrain in a 150-foot cube within range look, sound, and smell like another sort of natural terrain. The illusion includes ground texture and other features. A creature that uses its action to inspect it can make an Investigation check against your save DC to discern the illusion."},{"id":"ice_storm","level":4,"name":"Ice Storm","nameEn":"Ice Storm","school":"Evocation","castingTime":"1 Action","range":"300 feet","components":"V, S, M (a pinch of dust and a few drops of water)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A hail of rock-hard ice pounds to the ground in a 20-foot-radius, 40-foot-high cylinder. Each creature there must make a Dexterity saving throw, taking 2d8 bludgeoning and 4d6 cold damage on a failure or half on a success. The area becomes difficult terrain. The bludgeoning damage increases at higher levels."},{"id":"secret_chest","level":4,"name":"Leomund's Secret Chest","nameEn":"Leomund's Secret Chest","school":"Conjuration","castingTime":"1 Action","range":"Touch","components":"V, S, M (an exquisite chest worth at least 5,000 gp and a tiny replica)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You hide a chest and its contents on the Ethereal Plane. You must touch the chest and its miniature replica to cast it. As an action while holding the replica, you can recall the chest, which appears in an unoccupied space within 5 feet of you."},{"id":"locate_creature","level":4,"name":"Locate Creature","nameEn":"Locate Creature","school":"Divination","castingTime":"1 Action","range":"Self","components":"V, S, M (a bit of fur from a bloodhound)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"Describe or name a creature familiar to you. You sense the direction to the creature's location if it is within 1,000 feet. The spell can't locate it if running water at least 10 feet wide blocks a direct path, or if it is shielded by nondetection."},{"id":"mordenkainens_faithful_hound","level":4,"name":"Mordenkainen's Faithful Hound","nameEn":"Mordenkainen's Faithful Hound","school":"Conjuration","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a tiny silver whistle, a piece of bone, and a thread)","duration":"8 hours","concentration":false,"ritual":false,"description":"You conjure an invisible watchdog in an unoccupied space within range. It guards the area, barking loudly at hidden or invisible intruders, and bites any enemy within 5 feet for 4d8 piercing damage on a successful spell attack. It can't be harmed and vanishes if you move more than 30 feet from it."},{"id":"private_sanctum","level":4,"name":"Mordenkainen's Private Sanctum","nameEn":"Mordenkainen's Private Sanctum","school":"Abjuration","castingTime":"10 minutes","range":"120 feet","components":"V, S, M (a thin sheet of lead, a piece of glass, cotton, and powdered chrysolite)","duration":"24 hours","concentration":false,"ritual":false,"description":"You make an area within range magically secure. The area can be as large as a 100-foot cube. Choose effects: soundproofing, blocking divination scrying, preventing teleportation in or out, darkening or fogging, and blocking planar travel. You can recast it daily to make the effects permanent."},{"id":"otilukes_resilient_sphere","level":4,"name":"Otiluke's Resilient Sphere","nameEn":"Otiluke's Resilient Sphere","school":"Evocation","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a hemispherical piece of clear crystal and a matching gum elastic piece)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"A sphere of shimmering force encloses a creature or object of Large size or smaller within range. An unwilling creature can make a Dexterity save to avoid it. Nothing can pass through the sphere; the creature inside can't be harmed by outside effects, and vice versa. It can be rolled but is immune to damage."},{"id":"phantasmal_killer","level":4,"name":"Phantasmal Killer","nameEn":"Phantasmal Killer","school":"Illusion","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You tap into a creature's nightmares and create an illusory manifestation of its deepest fears, visible only to it. The target must succeed on a Wisdom saving throw or become frightened and take 4d10 psychic damage; it repeats the save at the end of each of its turns, taking the damage again on a failure. The damage increases at higher levels."},{"id":"polymorph","level":4,"name":"Polymorph","nameEn":"Polymorph","school":"Transmutation","castingTime":"1 Action","range":"60 feet","components":"V, S, M (a caterpillar cocoon)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You transform a creature you can see into a new beast form whose challenge rating is no higher than the target's CR (or level). An unwilling creature can resist with a Wisdom save. The target assumes the beast's stats and hit points, retaining its alignment and personality, and reverts when it drops to 0 hit points."},{"id":"staggering_smite","level":4,"name":"Staggering Smite","nameEn":"Staggering Smite","school":"Enchantment","castingTime":"1 Bonus Action","range":"Self","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"The next time you hit a creature with a melee weapon attack before the spell ends, your weapon pierces both body and mind, dealing an extra 4d6 psychic damage. The target must succeed on a Wisdom saving throw or have disadvantage on attacks and ability checks and be unable to take reactions until the end of its next turn."},{"id":"stone_shape","level":4,"name":"Stone Shape","nameEn":"Stone Shape","school":"Transmutation","castingTime":"1 Action","range":"Touch","components":"V, S, M (soft clay molded into the desired shape)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You touch a stone object of Medium size or smaller, or a section of stone no more than 5 feet in any dimension, and form it into any shape you like. You can make a passage, a weapon, or simple features, but the shape can have no moving parts."},{"id":"stoneskin","level":4,"name":"Stoneskin","nameEn":"Stoneskin","school":"Transmutation","castingTime":"1 Action","range":"Touch","components":"V, S, M (diamond dust worth 100 gp, consumed)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"This spell turns the flesh of a willing creature you touch as hard as stone. Until the spell ends, the target has resistance to nonmagical bludgeoning, piercing, and slashing damage."},{"id":"summon_aberration","level":4,"name":"Summon Aberration","nameEn":"Summon Aberration","school":"Conjuration","castingTime":"1 Action","range":"90 feet","components":"V, S, M (a pickled tentacle and an eyeball in a platinum-inlaid vial worth 400+ GP)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You call forth an aberrant spirit. It manifests in an unoccupied space that you can see within range and uses the Aberrant Spirit stat block. When you cast the spell, choose Beholderkin, Mind Flayer, or Slaad. The creature resembles an Aberration of that kind, which determines certain details in its stat block.\n\nThe creature disappears when it drops to 0 Hit Points or when the spell ends. The creature is an ally to you and your allies. In combat, it shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger.\n\nUsing a Higher-Level Spell Slot. Use the spell slot's level for the spell's level in the stat block."},{"id":"summon_construct","level":4,"name":"Summon Construct","nameEn":"Summon Construct","school":"Conjuration","castingTime":"1 Action","range":"90 feet","components":"V, S, M (a lockbox worth 400+ GP)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You call forth the spirit of a Construct. It manifests in an unoccupied space that you can see within range and uses the Construct Spirit stat block. When you cast the spell, choose a material: Clay, Metal, or Stone. The creature resembles an animate statue (you determine the appearance) made of the chosen material, which determines certain details in its stat block.\n\nThe creature disappears when it drops to 0 Hit Points or when the spell ends. The creature is an ally to you and your allies. In combat, the creature shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger.\n\nUsing a Higher-Level Spell Slot. Use the spell slot's level for the spell's level in the stat block."},{"id":"summon_elemental","level":4,"name":"Summon Elemental","nameEn":"Summon Elemental","school":"Conjuration","castingTime":"1 Action","range":"90 feet","components":"V, S, M (air, a pebble, ash, and water inside a gold-inlaid vial worth 400+ GP)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You call forth an Elemental spirit. It manifests in an unoccupied space that you can see within range and uses the Elemental Spirit stat block. When you cast the spell, choose an element: Air, Earth, Fire, or Water. The creature resembles a bipedal form wreathed in the chosen element, which determines certain details in its stat block.\n\nThe creature disappears when it drops to 0 Hit Points or when the spell ends. The creature is an ally to you and your allies. In combat, the creature shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger.\n\nUsing a Higher-Level Spell Slot. Use the spell slot's level for the spell's level in the stat block."},{"id":"vitriolic_sphere","level":4,"name":"Vitriolic Sphere","nameEn":"Vitriolic Sphere","school":"Evocation","castingTime":"1 Action","range":"150 feet","components":"V, S, M (a drop of bile)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You point at a location within range, and a glowing, 1-foot-diameter ball of acid streaks there and explodes in a 20-foot-radius Sphere. Each creature in that area makes a Dexterity saving throw. On a failed save, a creature takes 10d4 Acid damage and another 5d4 Acid damage at the end of its next turn. On a successful save, a creature takes half the initial damage only.\n\nUsing a Higher-Level Spell Slot. The initial damage increases by 2d4 for each spell slot level above 4."},{"id":"wall_of_fire","level":4,"name":"Wall of Fire","nameEn":"Wall of Fire","school":"Evocation","castingTime":"1 Action","range":"120 feet","components":"V, S, M (a small piece of phosphorus)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You create a wall of fire on a solid surface within range, up to 60 feet long, 20 feet high, and 1 foot thick, or a ring 20 feet in diameter. One side (your choice) deals 5d8 fire damage to creatures within 10 feet, and any creature that enters the wall or ends its turn within 10 feet makes a Dexterity save (half on success). The damage increases at higher levels."},{"id":"animate_objects","level":5,"name":"Animate Objects","nameEn":"Animate Objects","school":"Transmutation","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You bring up to ten nonmagical objects within range to life. You can animate Tiny to Large objects (a Huge counts as four). They act on your turn at your command, attacking your foes, and have stats based on their size. The number of objects increases at higher levels."},{"id":"antilife_shell","level":5,"name":"Antilife Shell","nameEn":"Antilife Shell","school":"Abjuration","castingTime":"1 Action","range":"Self (10-foot radius)","components":"V, S","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"A shimmering barrier extends from you in a 10-foot radius and moves with you. The barrier prevents living creatures (not constructs or undead) from passing or reaching through it, though they can use ranged attacks. It also prevents an affected creature from being affected by it if it was already inside when cast."},{"id":"awaken","level":5,"name":"Awaken","nameEn":"Awaken","school":"Transmutation","castingTime":"8 hours","range":"Touch","components":"V, S, M (an agate worth at least 1,000 gp, consumed)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"After spending the casting time tracing magical pathways, you touch a beast or plant with an Intelligence of 3 or lower. It gains an Intelligence of 10, the ability to speak one language you know, and movement and senses if a plant. It is charmed by you for 30 days and regards you with friendly affection thereafter."},{"id":"banishing_smite","level":5,"name":"Banishing Smite","nameEn":"Banishing Smite","school":"Conjuration","castingTime":"1 Bonus Action","range":"Self","components":"V","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"The next time you hit a creature with a weapon attack before the spell ends, it takes an extra 5d10 force damage. If this reduces it to 50 hit points or fewer, you also banish it (to a harmless demiplane if native to your plane, otherwise to its home plane) for the duration."},{"id":"bigbys_hand","level":5,"name":"Bigby's Hand","nameEn":"Bigby's Hand","school":"Evocation","castingTime":"1 Action","range":"120 feet","components":"V, S, M (an eggshell and a snakeskin glove)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You create a Large hand of shimmering force in an unoccupied space within range. It can deliver a clenched fist (2d8 force damage), force a target away, grasp and restrain a creature, or interpose itself to provide cover. As a bonus action you control its action each turn. The damage increases at higher levels."},{"id":"circle_of_power","level":5,"name":"Circle of Power","nameEn":"Circle of Power","school":"Abjuration","castingTime":"1 Action","range":"Self (30-foot radius)","components":"V","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"Divine energy radiates from you in a 30-foot aura that moves with you. Each creature of your choice in the aura has advantage on saving throws against spells and other magical effects, and when such a creature succeeds on a save that allows half damage, it instead takes none."},{"id":"cloudkill","level":5,"name":"Cloudkill","nameEn":"Cloudkill","school":"Conjuration","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You create a 20-foot-radius sphere of poisonous, yellow-green fog centered on a point within range. The area is heavily obscured. A creature that is fully within it or starts its turn there must make a Constitution save for 5d8 poison damage (half on success). The fog moves 10 feet away from you each round. The damage increases at higher levels."},{"id":"commune","level":5,"name":"Commune","nameEn":"Commune","school":"Divination","castingTime":"1 minute","range":"Self","components":"V, S, M (incense and a vial of holy or unholy water)","duration":"1 minute","concentration":false,"ritual":true,"description":"You contact your deity or a divine proxy and ask up to three questions that can be answered with yes or no. You receive a correct answer for each, though the entity isn't obligated to answer if it doesn't know."},{"id":"commune_with_nature","level":5,"name":"Commune with Nature","nameEn":"Commune with Nature","school":"Divination","castingTime":"1 minute","range":"Self","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":true,"description":"You become attuned to nature and gain knowledge of the surrounding territory (3 miles outdoors, 300 feet underground). You learn up to three facts about terrain, bodies of water, prevalent creatures, powerful celestials/fey/fiends/elementals/undead, and plant influences."},{"id":"cone_of_cold","level":5,"name":"Cone of Cold","nameEn":"Cone of Cold","school":"Evocation","castingTime":"1 Action","range":"Self (60-foot cone)","components":"V, S, M (a small crystal or glass cone)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A blast of cold air erupts from your hands. Each creature in a 60-foot cone must make a Constitution saving throw, taking 8d8 cold damage on a failure or half on a success. A creature killed by this spell becomes a frozen statue until it thaws. The damage increases by 1d8 per slot level above 5th."},{"id":"conjure_elemental","level":5,"name":"Conjure Elemental","nameEn":"Conjure Elemental","school":"Conjuration","castingTime":"1 Action","range":"90 feet","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You call forth an elemental of CR 5 or lower that appears in unoccupied space within range. It is friendly to you and your companions and obeys your commands; if your concentration breaks, it becomes hostile. It summons a more powerful elemental at higher levels."},{"id":"conjure_volley","level":5,"name":"Conjure Volley","nameEn":"Conjure Volley","school":"Conjuration","castingTime":"1 Action","range":"150 feet","components":"V, S, M (one piece of ammunition or a thrown weapon)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You fire ammunition or throw a weapon into the air to create a volley. A storm of identical weapons rains down in a 40-foot-radius, 20-foot-high cylinder centered on a point within range. Each creature there makes a Dexterity save for 8d8 damage of the weapon's type (half on success)."},{"id":"contact_other_plane","level":5,"name":"Contact Other Plane","nameEn":"Contact Other Plane","school":"Divination","castingTime":"1 minute","range":"Self","components":"V","duration":"1 minute","concentration":false,"ritual":true,"description":"You mentally contact a demigod, a long-dead sage, or another planar entity. Make a DC 15 Intelligence saving throw; on a failure you take 6d6 psychic damage and are insane until your next long rest. On a success, you can ask up to five questions, which the entity answers with one-word responses."},{"id":"contagion","level":5,"name":"Contagion","nameEn":"Contagion","school":"Necromancy","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"7 days","concentration":false,"ritual":false,"description":"Your touch inflicts disease. Make a melee spell attack; on a hit, you afflict the creature with a disease of your choice (such as Blinding Sickness or Slimy Doom). The target must make Constitution saves; after three failures it is fully afflicted with debilitating effects, or three successes ends it."},{"id":"creation","level":5,"name":"Creation","nameEn":"Creation","school":"Illusion","castingTime":"1 minute","range":"30 feet","components":"V, S, M (a tiny piece of matter of the same type as the item you plan to create)","duration":"Special","concentration":false,"ritual":false,"description":"You pull wisps of shadow material to create a nonliving object of vegetable matter, stone, metal, or another substance in a 5-foot cube. The object lasts a length of time based on its material (the more solid, the shorter). The size increases at higher levels."},{"id":"destructive_wave","level":5,"name":"Destructive Wave","nameEn":"Destructive Wave","school":"Evocation","castingTime":"1 Action","range":"Self (30-foot radius)","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You strike the ground, sending out divine energy. Each creature of your choice within 30 feet must make a Constitution saving throw, taking 5d6 thunder damage and 5d6 radiant or necrotic damage (your choice) on a failure and being knocked prone, or half damage and no prone on a success."},{"id":"dispel_evil_and_good","level":5,"name":"Dispel Evil and Good","nameEn":"Dispel Evil and Good","school":"Abjuration","castingTime":"1 Action","range":"Self","components":"V, S, M (holy water or powdered silver and iron)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Shimmering energy surrounds you, protecting against fey, undead, and creatures from beyond your plane. Such creatures have disadvantage on attacks against you. You can also use your action to break enchantment on a charmed/frightened/possessed creature, or to force a celestial, elemental, fey, fiend, or undead back to its home plane."},{"id":"dominate_person","level":5,"name":"Dominate Person","nameEn":"Dominate Person","school":"Enchantment","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You attempt to beguile a humanoid you can see within range. It must succeed on a Wisdom saving throw or be charmed for the duration, establishing a telepathic link through which you can command it. You can take total control as an action; the target repeats the save each time it takes damage. The duration lengthens at higher levels."},{"id":"dream","level":5,"name":"Dream","nameEn":"Dream","school":"Illusion","castingTime":"1 minute","range":"Special","components":"V, S, M (a handful of sand, a dab of ink, and a writing quill plucked from a sleeping bird)","duration":"8 hours","concentration":false,"ritual":false,"description":"You shape the dreams of a creature you know on the same plane. Choose a willing messenger who enters a trance and appears in the target's dreams, delivering a message of your choosing. You can make the dream a nightmare that deals 3d6 psychic damage and prevents the target from gaining rest."},{"id":"flame_strike","level":5,"name":"Flame Strike","nameEn":"Flame Strike","school":"Evocation","castingTime":"1 Action","range":"60 feet","components":"V, S, M (pinch of sulfur)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A vertical column of divine fire roars down in a 10-foot-radius, 40-foot-high cylinder within range. Each creature there must make a Dexterity saving throw, taking 4d6 fire damage and 4d6 radiant damage on a failure or half on a success. The fire damage increases by 1d6 per slot level above 5th."},{"id":"geas","level":5,"name":"Geas","nameEn":"Geas","school":"Enchantment","castingTime":"1 minute","range":"60 feet","components":"V","duration":"30 days","concentration":false,"ritual":false,"description":"You place a magical command on a creature you can see within range, forcing it to carry out a service or refrain from an action you specify. It must succeed on a Wisdom saving throw or be charmed; while charmed it takes 5d10 psychic damage each time it acts against your command (once per day). The duration lengthens at higher slot levels."},{"id":"greater_restoration","level":5,"name":"Greater Restoration","nameEn":"Greater Restoration","school":"Abjuration","castingTime":"1 Action","range":"Touch","components":"V, S, M (diamond dust worth at least 100 gp, consumed)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You imbue a creature you touch with positive energy to undo a debilitating effect. You can end one of the following: a charm or petrification, a curse (including attunement to a cursed item), any reduction to an ability score, or a reduction to its hit point maximum."},{"id":"hallow","level":5,"name":"Hallow","nameEn":"Hallow","school":"Abjuration","castingTime":"24 hours","range":"Touch","components":"V, S, M (herbs, oils, and incense worth at least 1,000 gp, consumed)","duration":"Until dispelled","concentration":false,"ritual":false,"description":"You touch a point and infuse an area around it (up to a 60-foot radius) with holy or unholy power. Specified creature types can't enter, be charmed/frightened/possessed there, and you bind an additional effect such as courage, darkness, daylight, or others to the area."},{"id":"hold_monster","level":5,"name":"Hold Monster","nameEn":"Hold Monster","school":"Enchantment","castingTime":"1 Action","range":"90 feet","components":"V, S, M (a small, straight piece of iron)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Choose a creature you can see within range (not undead). It must succeed on a Wisdom saving throw or be paralyzed for the duration, repeating the save at the end of each of its turns. You can target additional creatures at higher levels."},{"id":"insect_plague","level":5,"name":"Insect Plague","nameEn":"Insect Plague","school":"Conjuration","castingTime":"1 Action","range":"300 feet","components":"V, S, M (a few grains of sugar, some kernels of grain, and a smear of fat)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"Swarming, biting locusts fill a 20-foot-radius sphere within range. The area is lightly obscured and difficult terrain. A creature there when you cast it or that enters or starts its turn there makes a Constitution save for 4d10 piercing damage (half on success). The damage increases at higher levels."},{"id":"jallarzis_storm_of_radiance","level":5,"name":"Jallarzi's Storm of Radiance","nameEn":"Jallarzi's Storm of Radiance","school":"Evocation","castingTime":"1 Action","range":"120 feet","components":"V, S, M (a pinch of phosphorus)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You unleash a storm of flashing light and raging thunder in a 10-foot-radius, 40-foot-high Cylinder centered on a point you can see within range. While in this area, creatures have the Blinded and Deafened conditions, and they can't cast spells with a Verbal component.\n\nWhen the storm appears, each creature in it makes a Constitution saving throw, taking 2d10 Radiant damage and 2d10 Thunder damage on a failed save or half as much damage on a successful one. A creature also makes this save when it enters the spell's area for the first time on a turn or ends its turn there. A creature makes this save only once per turn.\n\nUsing a Higher-Level Spell Slot. The Radiant and Thunder damage increase by 1d10 for each spell slot level above 5."},{"id":"legend_lore","level":5,"name":"Legend Lore","nameEn":"Legend Lore","school":"Divination","castingTime":"10 minutes","range":"Self","components":"V, S, M (incense worth at least 250 gp and four ivory strips worth at least 50 gp each)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"Name or describe a person, place, or object. The spell brings to your mind a brief summary of the significant lore about that thing, as long as it is of legendary importance. The more information you already know, the more precise and detailed the lore."},{"id":"mass_cure_wounds","level":5,"name":"Mass Cure Wounds","nameEn":"Mass Cure Wounds","school":"Abjuration","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A wave of healing energy washes over creatures. Up to six creatures of your choice in a 30-foot-radius sphere within range each regain hit points equal to 3d8 + your spellcasting ability modifier. It has no effect on undead or constructs. The healing increases by 1d8 per slot level above 5th."},{"id":"mislead","level":5,"name":"Mislead","nameEn":"Mislead","school":"Illusion","castingTime":"1 Action","range":"Self","components":"S","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You become invisible at the same time that an illusory double of you appears where you are standing. The double moves at your command, and you can use your action to see and hear through its senses. The invisibility ends if you attack or cast a spell, but the illusory double persists."},{"id":"modify_memory","level":5,"name":"Modify Memory","nameEn":"Modify Memory","school":"Enchantment","castingTime":"1 Action","range":"30 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You attempt to reshape a creature's memories. One creature must succeed on a Wisdom saving throw or be charmed; while it is, you can change its memory of an event it experienced within the last 24 hours. You can eliminate a memory, modify details, or implant a false memory. Higher slots reach further back in time."},{"id":"passwall","level":5,"name":"Passwall","nameEn":"Passwall","school":"Transmutation","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a pinch of sesame seeds)","duration":"1 hour","concentration":false,"ritual":false,"description":"A passage appears at a point of your choice on a wooden, plaster, or stone surface within range, lasting for the duration. You choose its dimensions: up to 5 feet wide, 8 feet tall, and 20 feet deep. The passage creates no instability in the surrounding structure."},{"id":"planar_binding","level":5,"name":"Planar Binding","nameEn":"Planar Binding","school":"Abjuration","castingTime":"1 hour","range":"60 feet","components":"V, S, M (a jewel worth at least 1,000 gp, consumed)","duration":"24 hours","concentration":false,"ritual":false,"description":"You attempt to bind a celestial, elemental, fey, or fiend to your service. The creature must be within range for the whole casting and must succeed on a Charisma saving throw or be bound to serve you for the duration. The duration lengthens with higher slot levels."},{"id":"raise_dead","level":5,"name":"Raise Dead","nameEn":"Raise Dead","school":"Necromancy","castingTime":"1 hour","range":"Touch","components":"V, S, M (a diamond worth at least 500 gp, consumed)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You return a dead creature you touch to life, provided it has been dead no longer than 10 days. It returns with 1 hit point, but suffers a -4 penalty to attack rolls, saves, and ability checks that fades over a few days. The spell closes mortal wounds but doesn't restore missing body parts and neutralizes poisons."},{"id":"rarys_telepathic_bond","level":5,"name":"Rary's Telepathic Bond","nameEn":"Rary's Telepathic Bond","school":"Divination","castingTime":"1 Action","range":"30 feet","components":"V, S, M (pieces of eggshell from two different kinds of creatures)","duration":"1 hour","concentration":false,"ritual":true,"description":"You forge a telepathic link among up to eight willing creatures of your choice within range. Until the spell ends, the targets can communicate telepathically through the bond regardless of language, as long as they are on the same plane."},{"id":"reincarnate","level":5,"name":"Reincarnate","nameEn":"Reincarnate","school":"Necromancy","castingTime":"1 hour","range":"Touch","components":"V, S, M (rare oils and unguents worth at least 1,000 gp, consumed)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You touch a dead humanoid or a piece of one. Provided it has been dead no longer than 10 days, the spell forms a new adult body for the soul and calls it back. The creature returns to life with all its hit points, but in a new race determined randomly."},{"id":"scrying","level":5,"name":"Scrying","nameEn":"Scrying","school":"Divination","castingTime":"10 minutes","range":"Self","components":"V, S, M (a focus worth at least 1,000 gp, such as a mirror, crystal ball, or font of holy water)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You can see and hear a particular creature on the same plane. The target must make a Wisdom saving throw, modified by how well you know it and what connection you have to it. On a failure, an invisible sensor appears within 10 feet of the target that you can perceive through."},{"id":"seeming","level":5,"name":"Seeming","nameEn":"Seeming","school":"Illusion","castingTime":"1 Action","range":"30 feet","components":"V, S","duration":"8 hours","concentration":false,"ritual":false,"description":"This spell lets you change the appearance of any number of creatures you can see within range. You give each target a new illusory appearance, altering clothing, armor, weapons, and physical features. An unwilling creature can resist with a Charisma save, and inspection with an Investigation check can reveal the illusion."},{"id":"steel_wind_strike","level":5,"name":"Steel Wind Strike","nameEn":"Steel Wind Strike","school":"Conjuration","castingTime":"1 Action","range":"30 feet","components":"S, M (a melee weapon worth at least 1 sp)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You flourish the weapon used in casting and vanish to strike like the wind. Choose up to five creatures you can see within range; make a melee spell attack against each, dealing 6d10 force damage on a hit. You then teleport to an unoccupied space you can see within 5 feet of one of the targets."},{"id":"summon_celestial","level":5,"name":"Summon Celestial","nameEn":"Summon Celestial","school":"Conjuration","castingTime":"1 Action","range":"90 feet","components":"V, S, M (a reliquary worth 500+ GP)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You call forth a Celestial spirit. It manifests in an angelic form in an unoccupied space that you can see within range and uses the Celestial Spirit stat block. When you cast the spell, choose Avenger or Defender. Your choice determines certain details in its stat block.\n\nThe creature disappears when it drops to 0 Hit Points or when the spell ends. The creature is an ally to you and your allies. In combat, the creature shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger.\n\nUsing a Higher-Level Spell Slot. Use the spell slot's level for the spell's level in the stat block."},{"id":"summon_dragon","level":5,"name":"Summon Dragon","nameEn":"Summon Dragon","school":"Conjuration","castingTime":"1 Action","range":"60 feet","components":"V, S, M (an object with the image of a dragon engraved on it worth 500+ GP)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You call forth a Dragon spirit. It manifests in an unoccupied space that you can see within range and uses the Draconic Spirit stat block.\n\nThe creature disappears when it drops to 0 Hit Points or when the spell ends. The creature is an ally to you and your allies. In combat, the creature shares your Initiative count, but it takes its turn immediately after yours. It obeys your verbal commands (no action required by you). If you don't issue any, it takes the Dodge action and uses its movement to avoid danger.\n\nUsing a Higher-Level Spell Slot. Use the spell slot's level for the spell's level in the stat block."},{"id":"swift_quiver","level":5,"name":"Swift Quiver","nameEn":"Swift Quiver","school":"Transmutation","castingTime":"1 Bonus Action","range":"Touch","components":"V, S, M (a quiver containing at least one piece of ammunition)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You transmute a quiver you touch to magically produce ammunition. Until the spell ends, you can use a bonus action on each of your turns to make two attacks with a weapon that uses ammunition from the quiver, which produces its own."},{"id":"synaptic_static","level":5,"name":"Synaptic Static","nameEn":"Synaptic Static","school":"Enchantment","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You choose a point within range and crackling psychic energy explodes there. Each creature in a 20-foot-radius sphere must make an Intelligence saving throw, taking 8d6 psychic damage on a failure or half on a success. On a failure, a creature also has muddled thoughts: it subtracts 1d6 from attacks, checks, and Constitution saves for concentration for 1 minute."},{"id":"telekinesis","level":5,"name":"Telekinesis","nameEn":"Telekinesis","school":"Transmutation","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You gain the ability to move or manipulate creatures or objects by thought. Each round as an action you can try to move a creature (Strength contest) up to 30 feet, or move an object weighing up to 1,000 pounds, hurl it, or manipulate it with fine control."},{"id":"teleportation_circle","level":5,"name":"Teleportation Circle","nameEn":"Teleportation Circle","school":"Conjuration","castingTime":"1 minute","range":"10 feet","components":"V, M (rare chalks and inks infused with gems worth 50 gp, consumed)","duration":"1 round","concentration":false,"ritual":false,"description":"You draw a 10-foot-diameter circle on the ground inscribed with sigils that link to a permanent teleportation circle whose sigil sequence you know. A shimmering portal opens within the circle and remains until the end of your next turn, letting creatures step through to the destination circle."},{"id":"tree_stride","level":5,"name":"Tree Stride","nameEn":"Tree Stride","school":"Conjuration","castingTime":"1 Action","range":"Self","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You gain the ability to enter a tree and move from inside it to inside another tree of the same kind within 500 feet. Both trees must be living and at least the same size as you. You step into the tree using 5 feet of movement and emerge from the destination tree, using this once per round."},{"id":"wall_of_force","level":5,"name":"Wall of Force","nameEn":"Wall of Force","school":"Evocation","castingTime":"1 Action","range":"120 feet","components":"V, S, M (a pinch of powder made by crushing a clear gemstone)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"An invisible wall of force springs into existence at a point within range. You can shape it as a sphere or dome up to 10 feet in radius, or a flat surface of ten 10-foot-by-10-foot panels. Nothing can physically pass through it; it is immune to damage and can be destroyed only by disintegrate."},{"id":"wall_of_stone","level":5,"name":"Wall of Stone","nameEn":"Wall of Stone","school":"Evocation","castingTime":"1 Action","range":"120 feet","components":"V, S, M (a small block of granite)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"A nonmagical wall of solid stone springs into existence within range. The wall is 6 inches thick and made of ten 10-foot-by-10-foot panels you arrange to form a barrier, bridge, or ramp. If you concentrate for the full duration, the wall becomes permanent."},{"id":"yolandes_regal_presence","level":5,"name":"Yolande's Regal Presence","nameEn":"Yolande's Regal Presence","school":"Enchantment","castingTime":"1 Action","range":"Self","components":"V, S, M (a miniature tiara)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You surround yourself with unearthly majesty in a 10-foot Emanation.\n\nWhenever the Emanation enters the space of a creature you can see and whenever a creature you can see enters the Emanation or ends its turn there, you can force that creature to make a Wisdom saving throw. On a failed save, the target takes 4d6 Psychic damage and has the Prone condition, and you can push it up to 10 feet away. On a successful save, the target takes half as much damage only. A creature makes this save only once per turn."},{"id":"arcane_gate","level":6,"name":"Arcane Gate","nameEn":"Arcane Gate","school":"Conjuration","castingTime":"1 Action","range":"500 feet","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You create linked teleportation portals: a circular entrance portal and an exit portal, each a 10-foot-diameter ring within range. Any creature or object entering one portal exits from the other. As a bonus action you can rotate the facing of the portals."},{"id":"blade_barrier","level":6,"name":"Blade Barrier","nameEn":"Blade Barrier","school":"Evocation","castingTime":"1 Action","range":"90 feet","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You create a vertical wall of whirling, razor-sharp blades within range, providing three-quarters cover and being difficult terrain. A creature in the wall's area or that enters or ends its turn there makes a Dexterity save for 6d10 slashing damage (half on success). The wall can be a straight line or a ringed shape."},{"id":"chain_lightning","level":6,"name":"Chain Lightning","nameEn":"Chain Lightning","school":"Evocation","castingTime":"1 Action","range":"150 feet","components":"V, S, M (a bit of fur, a piece of amber, glass, or a crystal rod, and three silver pins)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You create a bolt of lightning that arcs toward a primary target, then leaps to as many as three secondary targets within 30 feet. Each must make a Dexterity saving throw, taking 10d8 lightning damage on a failure or half on a success. More targets are struck at higher levels."},{"id":"circle_of_death","level":6,"name":"Circle of Death","nameEn":"Circle of Death","school":"Necromancy","castingTime":"1 Action","range":"150 feet","components":"V, S, M (the powder of a crushed black pearl worth at least 500 gp)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A sphere of negative energy ripples out in a 60-foot-radius sphere from a point within range. Each creature there must make a Constitution saving throw, taking 8d6 necrotic damage on a failure or half on a success. The damage increases by 2d6 per slot level above 6th."},{"id":"conjure_fey","level":6,"name":"Conjure Fey","nameEn":"Conjure Fey","school":"Conjuration","castingTime":"1 Action","range":"90 feet","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You summon a fey creature of CR 6 or lower that appears in an unoccupied space within range. It is friendly to you and your companions while your concentration holds; otherwise it becomes hostile. A more powerful fey is summoned at higher levels."},{"id":"contingency","level":6,"name":"Contingency","nameEn":"Contingency","school":"Abjuration","castingTime":"10 minutes","range":"Self","components":"V, S, M (a statuette of yourself carved from ivory and decorated with gems worth at least 1,500 gp)","duration":"10 days","concentration":false,"ritual":false,"description":"You choose a spell of 5th level or lower that you can cast, that has a casting time of 1 action, and that targets you. You cast it as part of casting contingency, but its magic is stored until a circumstance you describe triggers it, at which point it is cast automatically."},{"id":"create_undead","level":6,"name":"Create Undead","nameEn":"Create Undead","school":"Necromancy","castingTime":"1 minute","range":"10 feet","components":"V, S, M (one clay pot filled with grave dirt, one with brackish water, and a 150 gp black onyx stone for each corpse)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You can animate up to three corpses within range as ghouls under your control. You command them mentally, and you can reassert and maintain control over them by recasting the spell. Higher slot levels animate more or more-powerful undead such as ghasts, wights, or mummies."},{"id":"disintegrate","level":6,"name":"Disintegrate","nameEn":"Disintegrate","school":"Transmutation","castingTime":"1 Action","range":"60 feet","components":"V, S, M (a lodestone and a pinch of dust)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A thin green ray springs from your finger to a target. A creature must make a Dexterity saving throw, taking 10d6 + 40 force damage on a failure; if this reduces it to 0 hit points, it is disintegrated into fine gray dust. It can also disintegrate a Large or smaller nonmagical object or a wall of force. The damage increases at higher levels."},{"id":"drawmijs_instant_summons","level":6,"name":"Drawmij's Instant Summons","nameEn":"Drawmij's Instant Summons","school":"Conjuration","castingTime":"1 minute","range":"Touch","components":"V, S, M (a sapphire worth 1,000 gp)","duration":"Until dispelled","concentration":false,"ritual":true,"description":"You touch an object weighing 10 pounds or less and inscribe a sapphire with its name. Thereafter, you can use your action to speak the item's name and crush the sapphire, and the object instantly appears in your hand no matter the distance, as long as it is on the same plane."},{"id":"eyebite","level":6,"name":"Eyebite","nameEn":"Eyebite","school":"Necromancy","castingTime":"1 Action","range":"Self","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"For the duration, your eyes become an inky void. Each of your turns you can target one creature within 60 feet that must succeed on a Wisdom saving throw or suffer an effect of your choice: Asleep (falls unconscious), Panicked (frightened and must flee), or Sickened (poisoned with disadvantage on attacks and checks)."},{"id":"find_the_path","level":6,"name":"Find the Path","nameEn":"Find the Path","school":"Divination","castingTime":"1 minute","range":"Self","components":"V, S, M (a set of divinatory tools worth 100 gp and an object from the location you wish to find)","duration":"Concentration, up to 1 day","concentration":true,"ritual":false,"description":"This spell lets you find the shortest, most direct physical route to a specific fixed location you are familiar with. For the duration, as long as you are on the same plane, you know the distance and direction to the location, and the most direct route."},{"id":"flesh_to_stone","level":6,"name":"Flesh to Stone","nameEn":"Flesh to Stone","school":"Transmutation","castingTime":"1 Action","range":"60 feet","components":"V, S, M (a pinch of lime, water, and earth)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You attempt to turn one creature into stone. It must make a Constitution saving throw; on a failure it is restrained, and it must save again at the end of each of its turns. After three failures it is petrified for the duration; three successes end the spell. If you concentrate for the full minute, the petrification is permanent."},{"id":"forbiddance","level":6,"name":"Forbiddance","nameEn":"Forbiddance","school":"Abjuration","castingTime":"10 minutes","range":"Touch","components":"V, S, M (a sprinkling of holy water, rare incense, and powdered ruby worth at least 1,000 gp)","duration":"1 day","concentration":false,"ritual":true,"description":"You create a ward against magical travel that protects an area up to a 40,000-square-foot space. Teleportation and planar travel in or out are blocked, and creatures of types you choose take 5d10 radiant or necrotic damage when they enter or start their turn there. Recasting daily for 30 days makes it permanent."},{"id":"globe_of_invulnerability","level":6,"name":"Globe of Invulnerability","nameEn":"Globe of Invulnerability","school":"Abjuration","castingTime":"1 Action","range":"Self (10-foot radius)","components":"V, S, M (a glass or crystal bead that shatters when the spell ends)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"An immobile, faintly shimmering barrier springs into existence in a 10-foot radius around you. Any spell of 5th level or lower cast from outside the barrier can't affect creatures or objects within it, even if cast at a higher level. The barrier blocks higher-level spells at higher slot levels."},{"id":"guards_and_wards","level":6,"name":"Guards and Wards","nameEn":"Guards and Wards","school":"Abjuration","castingTime":"1 hour","range":"Touch","components":"V, S, M (burning incense, a small measure of brimstone and oil, a knotted string, a small amount of umber hulk blood, and a small silver rod worth at least 10 gp)","duration":"24 hours","concentration":false,"ritual":false,"description":"You create a ward that protects up to 2,500 square feet of floor space. You set effects throughout the warded area: corridors filled with fog, doors locked with arcane lock, stairs webbed, and constant or one-time minor effects to confound intruders. Recasting daily for a year makes it permanent."},{"id":"harm","level":6,"name":"Harm","nameEn":"Harm","school":"Necromancy","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You unleash a virulent disease on a creature you can see within range. It must make a Constitution saving throw, taking 14d6 necrotic damage on a failure or half on a success. On a failure, its hit point maximum is reduced by the damage taken until it finishes a long rest. The spell can't reduce a target below 1 hit point."},{"id":"heal","level":6,"name":"Heal","nameEn":"Heal","school":"Abjuration","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"Choose a creature you can see within range. A surge of positive energy washes through it, restoring 70 hit points and ending blindness, deafness, and any diseases affecting it. It has no effect on undead or constructs. The healing increases by 10 per slot level above 6th."},{"id":"heroes_feast","level":6,"name":"Heroes' Feast","nameEn":"Heroes' Feast","school":"Conjuration","castingTime":"10 minutes","range":"30 feet","components":"V, S, M (a gem-encrusted bowl worth at least 1,000 gp, consumed)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You bring forth a great feast that takes 1 hour to consume. Up to twelve creatures that partake are cured of disease and poison, become immune to being poisoned and frightened, gain advantage on Wisdom saves, and have their hit point maximum increased by 2d10 for 24 hours."},{"id":"magic_jar","level":6,"name":"Magic Jar","nameEn":"Magic Jar","school":"Necromancy","castingTime":"1 minute","range":"Self","components":"V, S, M (a gem, crystal, reliquary, or other ornamental container worth at least 500 gp)","duration":"Until dispelled","concentration":false,"ritual":false,"description":"Your body falls into a catatonic state as your soul enters the container you used for the spell. From there you can attempt to possess a humanoid within 100 feet (Charisma save negates), taking control of its body while its soul is trapped in the container. You can return to the container or your own body as actions."},{"id":"mass_suggestion","level":6,"name":"Mass Suggestion","nameEn":"Mass Suggestion","school":"Enchantment","castingTime":"1 Action","range":"60 feet","components":"V, M (a snake's tongue and a honeycomb or sweet oil)","duration":"24 hours","concentration":false,"ritual":false,"description":"You suggest a course of activity (limited to a sentence or two) to up to twelve creatures you can see within range. Each must succeed on a Wisdom saving throw or pursue the suggested course as best it can, as long as it sounds reasonable. The duration lengthens with higher slot levels."},{"id":"move_earth","level":6,"name":"Move Earth","nameEn":"Move Earth","school":"Transmutation","castingTime":"1 Action","range":"120 feet","components":"V, S, M (an iron blade and a small bag of clay, loam, and sand)","duration":"Concentration, up to 2 hours","concentration":true,"ritual":false,"description":"You reshape dirt, sand, or clay in an area up to 40 feet on a side. You can raise or lower its elevation, dig trenches, raise mounds, or otherwise reshape terrain. Each 10-minute interval you can move the area or affect a new one. The change is too slow to trap or harm creatures."},{"id":"otilukes_freezing_sphere","level":6,"name":"Otiluke's Freezing Sphere","nameEn":"Otiluke's Freezing Sphere","school":"Evocation","castingTime":"1 Action","range":"300 feet","components":"V, S, M (a small crystal sphere)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A frigid globe streaks to a point within range and explodes in a 60-foot-radius sphere of cold. Each creature there must make a Constitution saving throw, taking 10d6 cold damage on a failure or half on a success. Water in the area freezes for 1 minute. The damage increases by 1d6 per slot level above 6th."},{"id":"ottos_irresistible_dance","level":6,"name":"Otto's Irresistible Dance","nameEn":"Otto's Irresistible Dance","school":"Enchantment","castingTime":"1 Action","range":"30 feet","components":"V","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"One creature you can see begins a comic dance: it must use all its movement to dance without leaving its space, has disadvantage on Dexterity saves and attack rolls, and other creatures have advantage on attacks against it. As an action on its turn, it can make a Wisdom save to end the effect."},{"id":"planar_ally","level":6,"name":"Planar Ally","nameEn":"Planar Ally","school":"Conjuration","castingTime":"10 minutes","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You beseech an otherworldly entity for aid, and a celestial, elemental, or fiend of the entity's choice appears within range. You may know the creature or simply request one of a general kind. The creature requires payment for its services, negotiated based on the tasks you ask of it."},{"id":"programmed_illusion","level":6,"name":"Programmed Illusion","nameEn":"Programmed Illusion","school":"Illusion","castingTime":"1 Action","range":"120 feet","components":"V, S, M (a bit of fleece and jade dust worth at least 25 gp)","duration":"Until dispelled","concentration":false,"ritual":false,"description":"You create an illusion of an object, creature, or phenomenon no larger than a 30-foot cube that activates when a specific condition occurs. The illusion includes sounds and can be set to repeat. Until triggered, it is imperceptible; physical interaction reveals it as illusory."},{"id":"summon_fiend","level":6,"name":"Summon Fiend","nameEn":"Summon Fiend","school":"Conjuration","castingTime":"1 Action","range":"90 feet","components":"V, S, M (a bloody vial containing zircon dust worth at least 600 gp)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You call forth a fiendish spirit that appears in an unoccupied space you can see within range. Choose its form: Demon, Devil, or Yugoloth. It is friendly to you and your companions, acts on your turn, and obeys your verbal commands; it grows stronger when summoned with a higher-level slot."},{"id":"sunbeam","level":6,"name":"Sunbeam","nameEn":"Sunbeam","school":"Evocation","castingTime":"1 Action","range":"Self (60-foot line)","components":"V, S, M (a magnifying glass)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"A beam of brilliant light flashes out in a 60-foot line, 5 feet wide. Each creature in it makes a Constitution save for 6d8 radiant damage and blindness until your next turn (half and no blindness on success). Until the spell ends you can use an action each turn to create a new line. Undead and oozes have disadvantage."},{"id":"tashas_bubbling_cauldron","level":6,"name":"Tasha's Bubbling Cauldron","nameEn":"Tasha's Bubbling Cauldron","school":"Conjuration","castingTime":"1 Action","range":"5 feet","components":"V, S, M (a gilded ladle worth 500+ GP)","duration":"10 minutes","concentration":false,"ritual":false,"description":"You conjure a claw-footed cauldron filled with bubbling liquid. The cauldron appears in an unoccupied space on the ground within 5 feet of you and lasts for the duration. The cauldron can't be moved, and disappears when the spell ends, along with the bubbling liquid inside of it.\n\nThe liquid in the cauldron duplicates the properties of a Common or an Uncommon potion of your choice (such as potion of healing). As a Bonus Action, you or an ally can reach into the cauldron and withdraw one potion of that kind. The potion is contained in a vial that disappears when the potion is consumed.\n\nThe cauldron can produce a number of these potions equal to your spellcasting ability modifier (minimum 1). When the last of these potions is withdrawn from the cauldron, the cauldron disappears, and the spell ends. Potions obtained from the cauldron that aren't consumed disappear when you cast the spell again."},{"id":"transport_via_plants","level":6,"name":"Transport via Plants","nameEn":"Transport via Plants","school":"Conjuration","castingTime":"1 Action","range":"10 feet","components":"V, S","duration":"1 minute","concentration":false,"ritual":false,"description":"This spell creates a magical link between a Large or larger inanimate plant within range and another plant, on the same plane, that you have seen or touched before. For the duration, any creature can step into the target plant and step out of the destination plant by using 5 feet of movement."},{"id":"true_seeing","level":6,"name":"True Seeing","nameEn":"True Seeing","school":"Divination","castingTime":"1 Action","range":"Touch","components":"V, S, M (an ointment for the eyes worth 25 gp, made from mushroom powder, saffron, and fat, consumed)","duration":"1 hour","concentration":false,"ritual":false,"description":"This spell gives the willing creature you touch true sight out to 120 feet for the duration. It can see in normal and magical darkness, see invisible creatures and objects, automatically detect visual illusions, perceive the original form of shapechangers, and see into the Ethereal Plane."},{"id":"wall_of_ice","level":6,"name":"Wall of Ice","nameEn":"Wall of Ice","school":"Evocation","castingTime":"1 Action","range":"120 feet","components":"V, S, M (a small piece of quartz)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You create a wall of ice on a solid surface within range, as a hemispherical dome, a sphere, or a flat surface of up to ten 10-foot-square panels, 1 foot thick. A creature in the wall's space when it appears makes a Dexterity save for 10d6 cold damage. Each panel has AC 12 and 30 hit points; breaking through deals 5d6 cold damage. The damage increases at higher levels."},{"id":"wall_of_thorns","level":6,"name":"Wall of Thorns","nameEn":"Wall of Thorns","school":"Conjuration","castingTime":"1 Action","range":"120 feet","components":"V, S, M (a handful of thorns)","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You create a wall of tough, pliable, tangled brush bristling with thorns, up to 60 feet long, 10 feet high, and 5 feet thick. It is difficult terrain, and a creature that enters or starts its turn there makes a Dexterity save for 7d8 piercing damage (half on success), plus damage for moving through. The damage increases at higher levels."},{"id":"wind_walk","level":6,"name":"Wind Walk","nameEn":"Wind Walk","school":"Transmutation","castingTime":"1 minute","range":"30 feet","components":"V, S, M (fire and holy water)","duration":"8 hours","concentration":false,"ritual":false,"description":"You and up to ten willing creatures within range assume a gaseous form for the duration, appearing as wisps of cloud. In cloud form a creature has a flying speed of 300 feet, resistance to nonmagical damage, and can't attack or cast spells. It takes 1 minute to transform to and from cloud form."},{"id":"word_of_recall","level":6,"name":"Word of Recall","nameEn":"Word of Recall","school":"Conjuration","castingTime":"1 Action","range":"5 feet","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You and up to five willing creatures within 5 feet instantly teleport to a previously designated sanctuary - a place you have consecrated and chosen during a ritual. The creatures appear in the nearest unoccupied spaces to the spot you designated."},{"id":"conjure_celestial","level":7,"name":"Conjure Celestial","nameEn":"Conjure Celestial","school":"Conjuration","castingTime":"1 Action","range":"90 feet","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You summon a celestial of CR 4 or lower that appears in an unoccupied space within range. It is friendly to you and your companions, acts on its own initiative, and obeys your verbal commands. A more powerful celestial (up to CR 5) is summoned at higher slot levels."},{"id":"delayed_blast_fireball","level":7,"name":"Delayed Blast Fireball","nameEn":"Delayed Blast Fireball","school":"Evocation","castingTime":"1 Action","range":"150 feet","components":"V, S, M (a tiny ball of bat guano and sulfur)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"A beam of yellow light flashes to a point and creates a glowing bead that pulses with energy. The bead grows more potent each round it isn't released, gaining 1d6 fire damage (starting at 12d6). When it detonates, each creature in a 20-foot-radius sphere makes a Dexterity save for the accumulated fire damage (half on success)."},{"id":"divine_word","level":7,"name":"Divine Word","nameEn":"Divine Word","school":"Evocation","castingTime":"1 Bonus Action","range":"30 feet","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You utter a word of power. Each creature of your choice that you can hear within range that fails a Charisma saving throw suffers an effect based on its current hit points: deafened, blinded, stunned, or killed, with weaker creatures suffering worse effects. Celestials, elementals, fey, and fiends that fail are forced back to their home plane."},{"id":"etherealness","level":7,"name":"Etherealness","nameEn":"Etherealness","school":"Conjuration","castingTime":"1 Action","range":"Self","components":"V, S","duration":"Up to 8 hours","concentration":false,"ritual":false,"description":"You step into the border region of the Ethereal Plane, in the area where it overlaps your current plane. You can move in any direction and perceive the plane you left in shades of gray, but can't see anything more than 60 feet away. While there, you can affect and be affected only by other creatures on the Ethereal Plane."},{"id":"finger_of_death","level":7,"name":"Finger of Death","nameEn":"Finger of Death","school":"Necromancy","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You send negative energy coursing through a creature you can see, causing it racking pain. It must make a Constitution saving throw, taking 7d8 + 30 necrotic damage on a failure or half on a success. A humanoid killed by this spell rises at the start of your next turn as a zombie under your permanent control."},{"id":"fire_storm","level":7,"name":"Fire Storm","nameEn":"Fire Storm","school":"Evocation","castingTime":"1 Action","range":"150 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A storm of roaring flame appears in a location you choose, filling an area made up of ten contiguous 10-foot cubes. Each creature there must make a Dexterity saving throw, taking 7d10 fire damage on a failure or half on a success. The fire damages objects and ignites flammables, but you can choose to leave plant life unharmed."},{"id":"forcecage","level":7,"name":"Forcecage","nameEn":"Forcecage","school":"Evocation","castingTime":"1 Action","range":"100 feet","components":"V, S, M (ruby dust worth 1,500 gp, consumed)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"An immobile, invisible, cube-shaped prison of magical force springs into existence. You can make it a 20-foot cage with bars, or a 10-foot solid box. A creature inside can't leave by nonmagical means, and a creature attempting to teleport or planar travel out must succeed on a Charisma saving throw."},{"id":"mirage_arcane","level":7,"name":"Mirage Arcane","nameEn":"Mirage Arcane","school":"Illusion","castingTime":"10 minutes","range":"Sight","components":"V, S","duration":"10 days","concentration":false,"ritual":false,"description":"You make terrain in an area up to 1 mile square look, sound, smell, and feel like another sort of terrain. You can add or conceal structures and features, and even create tactile illusions so that solid objects seem to exist. A creature with truesight sees through it."},{"id":"mordenkainens_magnificent_mansion","level":7,"name":"Mordenkainen's Magnificent Mansion","nameEn":"Mordenkainen's Magnificent Mansion","school":"Conjuration","castingTime":"1 minute","range":"300 feet","components":"V, S, M (a miniature ivory door, a piece of polished marble, and a silver spoon, each worth at least 5 gp)","duration":"24 hours","concentration":false,"ritual":false,"description":"You conjure an extradimensional dwelling within range, with an entrance you can see that only creatures you designate can enter. The opulent interior can hold up to 100 people, and a staff of translucent servants attends all who enter, providing food and drink."},{"id":"mordenkainens_sword","level":7,"name":"Mordenkainen's Sword","nameEn":"Mordenkainen's Sword","school":"Evocation","castingTime":"1 Action","range":"60 feet","components":"V, S, M (a miniature platinum sword with a grip and pommel of copper and zinc, worth 250 gp)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You create a sword-shaped plane of force that hovers within range. It lasts for the duration, and you can use a bonus action to move it up to 20 feet and make a melee spell attack against a target within 5 feet of it, dealing 3d10 force damage on a hit."},{"id":"plane_shift","level":7,"name":"Plane Shift","nameEn":"Plane Shift","school":"Conjuration","castingTime":"1 Action","range":"Touch","components":"V, S, M (a forked, metal rod worth at least 250 gp, attuned to a particular plane)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You and up to eight willing creatures who link hands in a circle are transported to a different plane of existence. Alternatively, you can use the spell to banish an unwilling creature you touch to another plane if it fails a Charisma saving throw."},{"id":"power_word_fortify","level":7,"name":"Power Word Fortify","nameEn":"Power Word Fortify","school":"Enchantment","castingTime":"1 Action","range":"60 feet","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You fortify up to six creatures of your choice within range. Divide 120 Temporary Hit Points among the chosen creatures."},{"id":"prismatic_spray","level":7,"name":"Prismatic Spray","nameEn":"Prismatic Spray","school":"Evocation","castingTime":"1 Action","range":"Self (60-foot cone)","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"Eight multicolored rays of light flash from your hand in a 60-foot cone. Each creature there must make a Dexterity saving throw; for each, roll a d8 to determine which colored ray strikes it, dealing fire, acid, lightning, poison, or cold damage, or causing restraint/petrification, blindness/banishment, or other effects."},{"id":"project_image","level":7,"name":"Project Image","nameEn":"Project Image","school":"Illusion","castingTime":"1 Action","range":"500 miles","components":"V, S, M (a small replica of you made from materials worth at least 5 gp)","duration":"Concentration, up to 1 day","concentration":true,"ritual":false,"description":"You create an illusory copy of yourself that lasts for the duration. The copy can appear at any location within range that you have seen before, and it looks and sounds like you but is intangible. You can use your action to see through its eyes and speak through it as though you were present."},{"id":"regenerate","level":7,"name":"Regenerate","nameEn":"Regenerate","school":"Transmutation","castingTime":"1 minute","range":"Touch","components":"V, S, M (a prayer wheel and holy water)","duration":"1 hour","concentration":false,"ritual":false,"description":"You touch a creature and stimulate its natural healing. It regains 4d8 + 15 hit points immediately, and at the start of each of its turns for the duration it regains 1 hit point. Severed body parts are restored after 2 minutes, reattaching or regrowing."},{"id":"resurrection","level":7,"name":"Resurrection","nameEn":"Resurrection","school":"Necromancy","castingTime":"1 hour","range":"Touch","components":"V, S, M (a diamond worth at least 1,000 gp, consumed)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You touch a dead creature that has been dead no more than a century, didn't die of old age, and isn't undead. It returns to life with all its hit points, and the spell neutralizes poisons, cures diseases, and closes wounds, though it suffers a fading penalty to rolls for a few days."},{"id":"reverse_gravity","level":7,"name":"Reverse Gravity","nameEn":"Reverse Gravity","school":"Transmutation","castingTime":"1 Action","range":"100 feet","components":"V, S, M (a lodestone and iron filings)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"This spell reverses gravity in a 50-foot-radius, 100-foot-high cylinder centered on a point within range. All creatures and objects that aren't anchored fall upward and reach the top of the area. A creature can make a Dexterity save to grab onto a fixed object. When the spell ends, affected objects and creatures fall back down."},{"id":"sequester","level":7,"name":"Sequester","nameEn":"Sequester","school":"Transmutation","castingTime":"1 Action","range":"Touch","components":"V, S, M (a powder of diamond, emerald, ruby, and sapphire worth at least 5,000 gp, consumed)","duration":"Until dispelled","concentration":false,"ritual":false,"description":"By means of this spell, a willing creature or an object can be hidden away from detection. The target becomes invisible, can't be targeted by divination spells or perceived by scrying, and if it is a creature, it falls into suspended animation. You can set a trigger condition to end the spell."},{"id":"simulacrum","level":7,"name":"Simulacrum","nameEn":"Simulacrum","school":"Illusion","castingTime":"12 hours","range":"Touch","components":"V, S, M (snow or ice, the powdered ruby or sapphire dust worth 1,500 gp sprinkled, and a piece of the creature being duplicated)","duration":"Until dispelled","concentration":false,"ritual":false,"description":"You shape an illusory duplicate of one beast or humanoid that is within touch for the spell's casting time. The duplicate is a creature with half the original's hit point maximum, obeys you, and acts on its own initiative. It can't gain hit points by normal means or regain spell slots."},{"id":"symbol","level":7,"name":"Symbol","nameEn":"Symbol","school":"Abjuration","castingTime":"1 minute","range":"Touch","components":"V, S, M (mercury, phosphorus, and powdered diamond and opal worth at least 1,000 gp, consumed)","duration":"Until dispelled or triggered","concentration":false,"ritual":false,"description":"You inscribe a harmful glyph on a surface or within an object. When triggered by a condition you set, the glyph erupts in a 60-foot-radius sphere with an effect of your choice: death, discord, fear, pain, sleep, stunning, insanity, or hopelessness."},{"id":"teleport","level":7,"name":"Teleport","nameEn":"Teleport","school":"Conjuration","castingTime":"1 Action","range":"10 feet","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"This spell instantly transports you and up to eight willing creatures of your choice (or a single object) to a destination you select, on the same plane. Your familiarity with the destination determines whether you arrive on target, off target, or somewhere unexpected, based on a roll."},{"id":"animal_shapes","level":8,"name":"Animal Shapes","nameEn":"Animal Shapes","school":"Transmutation","castingTime":"1 Action","range":"30 feet","components":"V, S","duration":"24 hours","concentration":false,"ritual":false,"description":"Your magic turns others into beasts. Choose any number of willing creatures you can see within range. You transform each into a Large or smaller beast with a challenge rating of 4 or lower. On later turns you can use your action to transform affected creatures into new forms."},{"id":"antimagic_field","level":8,"name":"Antimagic Field","nameEn":"Antimagic Field","school":"Abjuration","castingTime":"1 Action","range":"Self (10-foot radius)","components":"V, S, M (a pinch of powdered iron or iron filings)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"A 10-foot-radius invisible sphere of antimagic surrounds you and moves with you. Within it, spells can't be cast, magic items lose their properties, summoned creatures temporarily wink out, and ongoing spell effects are suppressed. The field suppresses but doesn't dispel magic."},{"id":"antipathy_sympathy","level":8,"name":"Antipathy/Sympathy","nameEn":"Antipathy/Sympathy","school":"Enchantment","castingTime":"1 hour","range":"60 feet","components":"V, S, M (either a lump of alum soaked in vinegar for antipathy or a drop of honey for sympathy)","duration":"10 days","concentration":false,"ritual":false,"description":"You set a magical effect on a creature or object that either repels or attracts a kind of intelligent creature you specify. An affected creature that can see or be within 60 feet must make a Wisdom save; on a failure it is compelled to flee from (antipathy) or approach (sympathy) the target as long as it remains nearby."},{"id":"befuddlement","level":8,"name":"Befuddlement","nameEn":"Befuddlement","school":"Enchantment","castingTime":"1 Action","range":"150 feet","components":"V, S, M (a key ring with no keys)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You blast the mind of a creature that you can see within range. The target makes an Intelligence saving throw. On a failed save, the target takes 10d12 Psychic damage and can't cast spells or take the Magic action.\n\nAt the end of every 30 days, the target repeats the save, ending the effect on a success. The effect can also be ended by the Greater Restoration, Heal, or Wish spell.\n\nOn a successful save, the target takes half as much damage only."},{"id":"clone","level":8,"name":"Clone","nameEn":"Clone","school":"Necromancy","castingTime":"1 hour","range":"Touch","components":"V, S, M (a diamond worth at least 1,000 gp and a vessel worth at least 2,000 gp, with a sealable lid, large enough to hold a Medium creature)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You grow an inert duplicate of a living creature as a safeguard against death. The clone forms inside a sealed vessel over 120 days. If the original creature dies, its soul transfers to the clone, provided the soul is free and willing, and the clone becomes the creature with all its memories."},{"id":"control_weather","level":8,"name":"Control Weather","nameEn":"Control Weather","school":"Transmutation","castingTime":"10 minutes","range":"Self (5-mile radius)","components":"V, S, M (burning incense and bits of earth and wood mixed in water)","duration":"Concentration, up to 8 hours","concentration":true,"ritual":false,"description":"You take control of the weather within 5 miles of you for the duration. You must be outdoors. You can change precipitation, temperature, and wind, each by stages up or down from the current conditions, with changes taking effect over time."},{"id":"demiplane","level":8,"name":"Demiplane","nameEn":"Demiplane","school":"Conjuration","castingTime":"1 Action","range":"60 feet","components":"S","duration":"1 hour","concentration":false,"ritual":false,"description":"You create a shadowy door on a flat solid surface you can see within range. The door leads to a 30-foot-cube demiplane, an empty room of wood or stone. When the spell ends, the door vanishes, and any creatures or objects inside the demiplane remain trapped until you reopen access."},{"id":"dominate_monster","level":8,"name":"Dominate Monster","nameEn":"Dominate Monster","school":"Enchantment","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You attempt to beguile a creature you can see within range. It must succeed on a Wisdom saving throw or be charmed for the duration, establishing a telepathic link through which you can command it. You can take total control as an action; the target repeats the save each time it takes damage. The duration lengthens at higher slot levels."},{"id":"earthquake","level":8,"name":"Earthquake","nameEn":"Earthquake","school":"Transmutation","castingTime":"1 Action","range":"500 feet","components":"V, S, M (a pinch of dirt, a piece of rock, and a lump of clay)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You create a seismic disturbance in a 100-foot-radius circle centered on a point on the ground within range. The ground becomes difficult terrain, creatures concentrating must save, creatures are knocked prone, fissures open swallowing creatures, and structures take damage and may collapse on those nearby."},{"id":"glibness","level":8,"name":"Glibness","nameEn":"Glibness","school":"Enchantment","castingTime":"1 Action","range":"Self","components":"V","duration":"1 hour","concentration":false,"ritual":false,"description":"Until the spell ends, when you make a Charisma check, you can replace the number you roll with a 15. Additionally, no matter what you say, magic that would determine if you are telling the truth indicates that you are being truthful."},{"id":"holy_aura","level":8,"name":"Holy Aura","nameEn":"Holy Aura","school":"Abjuration","castingTime":"1 Action","range":"Self (30-foot radius)","components":"V, S, M (a tiny reliquary worth at least 1,000 gp containing a sacred relic)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Divine light washes out from you in a 30-foot radius. Each creature of your choice in the area sheds dim light, gains advantage on saving throws, and other creatures have disadvantage on attacks against it. If a fiend or undead hits a protected creature with a melee attack, it must save or be blinded."},{"id":"incendiary_cloud","level":8,"name":"Incendiary Cloud","nameEn":"Incendiary Cloud","school":"Conjuration","castingTime":"1 Action","range":"150 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"A swirling cloud of smoke shot through with embers appears in a 20-foot-radius sphere within range. The cloud heavily obscures the area. A creature there when it appears or that enters or ends its turn there makes a Dexterity save for 10d8 fire damage (half on success). The cloud moves 10 feet away from you each round."},{"id":"maze","level":8,"name":"Maze","nameEn":"Maze","school":"Conjuration","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Concentration, up to 10 minutes","concentration":true,"ritual":false,"description":"You banish a creature you can see within range into a labyrinthine demiplane. It remains there for the duration or until it escapes the maze by using its action to make a DC 20 Intelligence check to find the exit. When it leaves or the spell ends, it reappears in the space it left or the nearest unoccupied space."},{"id":"mind_blank","level":8,"name":"Mind Blank","nameEn":"Mind Blank","school":"Abjuration","castingTime":"1 Action","range":"Touch","components":"V, S","duration":"24 hours","concentration":false,"ritual":false,"description":"Until the spell ends, one willing creature you touch is immune to psychic damage, any effect that would sense its emotions or read its thoughts, divination spells, and the charmed condition. The spell even foils wish spells and effects used to affect the target's mind or gain information about it."},{"id":"power_word_stun","level":8,"name":"Power Word Stun","nameEn":"Power Word Stun","school":"Enchantment","castingTime":"1 Action","range":"60 feet","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You speak a word of power that can overwhelm the mind of one creature you can see within range, leaving it dumbfounded. If the target has 150 hit points or fewer, it is stunned; otherwise it is unaffected. The stunned target can make a Constitution saving throw at the end of each of its turns to end the effect."},{"id":"sunburst","level":8,"name":"Sunburst","nameEn":"Sunburst","school":"Evocation","castingTime":"1 Action","range":"150 feet","components":"V, S, M (fire and a piece of sunstone)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"Brilliant sunlight flashes in a 60-foot-radius sphere centered on a point within range. Each creature there must make a Constitution saving throw, taking 12d6 radiant damage and being blinded for 1 minute on a failure, or half damage and no blindness on a success. Undead and oozes have disadvantage."},{"id":"telepathy","level":8,"name":"Telepathy","nameEn":"Telepathy","school":"Divination","castingTime":"1 Action","range":"Unlimited","components":"V, S, M (a pair of linked silver rings)","duration":"24 hours","concentration":false,"ritual":false,"description":"You create a telepathic link with one willing creature you are familiar with. The link works regardless of distance as long as you are on the same plane. The two of you can communicate thoughts, images, sounds, and other sensory messages through the link."},{"id":"tsunami","level":8,"name":"Tsunami","nameEn":"Tsunami","school":"Conjuration","castingTime":"1 minute","range":"Sight","components":"V, S","duration":"Concentration, up to 6 rounds","concentration":true,"ritual":false,"description":"A wall of water 300 feet long, 300 feet high, and 50 feet thick appears at a point you can see. Each creature in it makes a Strength save for 6d10 bludgeoning damage (half on success). Each round the wall loses height and moves away from you, dealing reduced damage and making the area difficult terrain."},{"id":"astral_projection","level":9,"name":"Astral Projection","nameEn":"Astral Projection","school":"Necromancy","castingTime":"1 hour","range":"10 feet","components":"V, S, M (for each creature: a jacinth worth at least 1,000 gp and an ornately carved silver bar worth at least 100 gp, all consumed)","duration":"Until dispelled","concentration":false,"ritual":false,"description":"You and up to eight willing creatures within range project your astral bodies onto the Astral Plane, leaving your physical bodies behind in suspended animation. Your astral form can travel the Astral Plane and into other planes; if it is killed, your physical body dies. A silver cord links the two."},{"id":"foresight","level":9,"name":"Foresight","nameEn":"Foresight","school":"Divination","castingTime":"1 minute","range":"Touch","components":"V, S, M (a hummingbird feather)","duration":"8 hours","concentration":false,"ritual":false,"description":"You touch a willing creature and bestow limited prescience. For the duration, the target can't be surprised and has advantage on attack rolls, ability checks, and saving throws. Additionally, other creatures have disadvantage on attack rolls against it. The spell ends early if you cast it again."},{"id":"gate","level":9,"name":"Gate","nameEn":"Gate","school":"Conjuration","castingTime":"1 Action","range":"60 feet","components":"V, S, M (a diamond worth at least 5,000 gp)","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"You conjure a circular portal linking an unoccupied space you can see within range to a precise location on a different plane. The portal is a 5-to-20-foot-diameter ring that travels both ways. You can also use it to summon a specific creature by speaking its name as the gate opens."},{"id":"imprisonment","level":9,"name":"Imprisonment","nameEn":"Imprisonment","school":"Abjuration","castingTime":"1 minute","range":"30 feet","components":"V, S, M (a vellum depiction or carved statuette of the target, plus a special component for the chosen mode worth at least 500 gp per Hit Die)","duration":"Until dispelled","concentration":false,"ritual":false,"description":"You create a magical restraint to hold a creature you can see within range. It must succeed on a Wisdom saving throw or be bound by one mode you choose: Burial deep underground, Chaining, Hedged Prison in a demiplane, Minimus Containment in a gem, or Slumber in eternal sleep."},{"id":"mass_heal","level":9,"name":"Mass Heal","nameEn":"Mass Heal","school":"Abjuration","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A flood of healing energy flows from you into injured creatures around you. You restore up to 700 hit points, divided as you choose among any number of creatures you can see within range. The spell also ends blindness, deafness, and any diseases on those creatures. It has no effect on undead or constructs."},{"id":"meteor_swarm","level":9,"name":"Meteor Swarm","nameEn":"Meteor Swarm","school":"Evocation","castingTime":"1 Action","range":"1 mile","components":"V, S","duration":"Instantaneous","concentration":false,"ritual":false,"description":"Blazing orbs of fire plummet to the ground at four different points you can see within range. Each creature in a 40-foot-radius sphere around each point must make a Dexterity saving throw, taking 20d6 fire damage and 20d6 bludgeoning damage on a failure or half on a success. A creature in multiple areas is affected only once."},{"id":"power_word_heal","level":9,"name":"Power Word Heal","nameEn":"Power Word Heal","school":"Enchantment","castingTime":"1 Action","range":"Touch","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"A wave of healing energy washes over the creature you touch. It regains all its hit points. If it is charmed, frightened, paralyzed, or stunned, the condition ends, and if it is prone, it can use its reaction to stand up. This spell has no effect on undead or constructs."},{"id":"power_word_kill","level":9,"name":"Power Word Kill","nameEn":"Power Word Kill","school":"Enchantment","castingTime":"1 Action","range":"60 feet","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You utter a word of power that can compel one creature you can see within range to die instantly. If the target has 100 hit points or fewer, it dies. Otherwise, the spell has no effect."},{"id":"prismatic_wall","level":9,"name":"Prismatic Wall","nameEn":"Prismatic Wall","school":"Abjuration","castingTime":"1 Action","range":"60 feet","components":"V, S","duration":"10 minutes","concentration":false,"ritual":false,"description":"A shimmering, multicolored plane of light forms a vertical wall (up to 90 feet long, 30 feet high, 1 inch thick) or a sphere within range. It has seven layers, each a different color with its own deadly effect; a creature that tries to pass through must contend with each layer in turn, suffering damage and conditions."},{"id":"shapechange","level":9,"name":"Shapechange","nameEn":"Shapechange","school":"Transmutation","castingTime":"1 Action","range":"Self","components":"V, S, M (a jade circlet worth at least 1,500 gp, worn on the head)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You assume the form of a different creature for the duration. The new form can be of any creature with a challenge rating no higher than your level, and you can't choose a construct or undead. You gain the form's statistics while retaining your alignment, personality, and ability to speak, and you can change forms as an action."},{"id":"storm_of_vengeance","level":9,"name":"Storm of Vengeance","nameEn":"Storm of Vengeance","school":"Conjuration","castingTime":"1 Action","range":"Sight","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"A churning storm cloud forms in a 360-foot-radius area. Each round it unleashes a new effect: thunderous booms that deal thunder damage and deafen, acid rain, lightning bolts, hailstones, and finally freezing rain that creates difficult terrain and reduces visibility. Each effect requires saving throws from creatures beneath the storm."},{"id":"time_stop","level":9,"name":"Time Stop","nameEn":"Time Stop","school":"Transmutation","castingTime":"1 Action","range":"Self","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You briefly stop the flow of time for everyone but yourself. You take 1d4 + 1 turns in a row, during which you can act and move as normal. The spell ends if one of your actions or effects affects a creature other than you or an object being worn or carried by someone else, or if you move more than 1,000 feet from where you cast it."},{"id":"true_polymorph","level":9,"name":"True Polymorph","nameEn":"True Polymorph","school":"Transmutation","castingTime":"1 Action","range":"30 feet","components":"V, S, M (a drop of mercury, a dollop of gum arabic, and a wisp of smoke)","duration":"Concentration, up to 1 hour","concentration":true,"ritual":false,"description":"You transform one creature or nonmagical object you can see into a different creature or object. An unwilling creature can resist with a Wisdom save. You can turn a creature into another creature, a creature into an object, or an object into a creature (with a CR or level no higher than the target's). If you concentrate for the full hour, the transformation becomes permanent."},{"id":"true_resurrection","level":9,"name":"True Resurrection","nameEn":"True Resurrection","school":"Necromancy","castingTime":"1 hour","range":"Touch","components":"V, S, M (a sprinkle of holy water and diamonds worth at least 25,000 gp, consumed)","duration":"Instantaneous","concentration":false,"ritual":false,"description":"You touch a creature that has been dead for no longer than 200 years and didn't die of old age. It returns to life with all its hit points, and the spell closes all wounds, neutralizes poison, cures diseases, and restores missing body parts. You can even resurrect a creature if you speak its name, and the spell forms a new body if needed."},{"id":"weird","level":9,"name":"Weird","nameEn":"Weird","school":"Illusion","castingTime":"1 Action","range":"120 feet","components":"V, S","duration":"Concentration, up to 1 minute","concentration":true,"ritual":false,"description":"Drawing on the deepest fears of a group of creatures, you create illusory creatures in their minds. Each creature in a 30-foot-radius sphere must make a Wisdom save or take 10d10 psychic damage and become frightened. While frightened, it takes 4d10 psychic damage at the end of each of its turns; it can repeat the save to end the effect."},{"id":"wish","level":9,"name":"Wish","nameEn":"Wish","school":"Conjuration","castingTime":"1 Action","range":"Self","components":"V","duration":"Instantaneous","concentration":false,"ritual":false,"description":"The mightiest spell a mortal creature can cast. By simply speaking aloud, you can alter the very foundations of reality. You can duplicate any other spell of 8th level or lower, or produce one of several greater effects: undo recent events, grant resistances, or other wishes. Casting greater wishes carries a risk of great stress that may prevent you from ever casting wish again."}];
